/* ===================== HOOKS ============================================== */
function useReveal() {
  const ref = useRef(null);
  const [inView, setIn] = useState(false);
  useEffect(() => {
    const el = ref.current; if (!el) return;
    const io = new IntersectionObserver(
      es => es.forEach(e => e.isIntersecting && (setIn(true), io.disconnect())),
      { threshold: .14 });
    io.observe(el); return () => io.disconnect();
  }, []);
  return [ref, inView];
}
function Reveal({ children, delay = 0, className, style }) {
  const [ref, on] = useReveal();
  return (
    <div ref={ref} className={className} style={{
      opacity: on ? 1 : 0,
      transform: on ? "none" : "translateY(20px) scale(.975)",
      transition: `opacity .7s ${delay}s ease-out, transform .7s ${delay}s cubic-bezier(.34,1.4,.64,1)`,
      ...style
    }}>{children}</div>
  );
}
function useMedia(q) {
  const [m, setM] = useState(() => typeof window !== "undefined" && window.matchMedia(q).matches);
  useEffect(() => {
    const mm = window.matchMedia(q); const h = e => setM(e.matches);
    mm.addEventListener("change", h); setM(mm.matches);
    return () => mm.removeEventListener("change", h);
  }, [q]);
  return m;
}

/* ===================== SONIDO ============================================
   Todo se sintetiza en el navegador: no hay un solo archivo de audio todavía.
   Dos piezas: el paisaje de fondo (mar en bucle) y los avisos de transición,
   uno distinto por sección. Cuando lleguen las grabaciones de campo se
   reemplazan por archivos reales sin tocar el resto del componente.        */

function bufferRuido(ctx, seg) {
  const sr = ctx.sampleRate;
  const b = ctx.createBuffer(1, Math.floor(sr * seg), sr), d = b.getChannelData(0);
  let b0 = 0, b1 = 0, b2 = 0;
  for (let i = 0; i < d.length; i++) {
    const w = Math.random() * 2 - 1;
    b0 = .997 * b0 + w * .0555; b1 = .985 * b1 + w * .0750; b2 = .950 * b2 + w * .1538;
    d[i] = (b0 + b1 + b2 + w * .02) * .38;
  }
  return b;
}

/* Cada aviso es una receta corta de osciladores y ruido filtrado. */
const AVISOS = {
  /* Coro del monte. Un canto de verdad no es un pitido: tiene timbre con
     armónicos, un contorno de tono propio y casi siempre trino. Cada llamada
     lleva su forma, y se solapan a distintas distancias. */
  pajaros(ctx, dest, t0) {
    const canto = (t, o) => {
      const { f0, f1, f2, dur = .24, trino = 0, vel = 34, vol = .3 } = o;
      const osc = ctx.createOscillator(); osc.type = "triangle";
      const bp = ctx.createBiquadFilter(); bp.type = "bandpass"; bp.Q.value = 3.2;
      const g = ctx.createGain();
      osc.frequency.setValueAtTime(f0, t);
      osc.frequency.exponentialRampToValueAtTime(f1, t + dur * .38);
      osc.frequency.exponentialRampToValueAtTime(f2, t + dur);
      bp.frequency.setValueAtTime(f0 * 1.7, t);
      bp.frequency.exponentialRampToValueAtTime(f2 * 1.7, t + dur);
      if (trino) {                                   // el temblor del canto
        const lfo = ctx.createOscillator(); lfo.type = "sine"; lfo.frequency.value = vel;
        const lg = ctx.createGain(); lg.gain.value = trino;
        lfo.connect(lg); lg.connect(osc.frequency);
        lfo.start(t); lfo.stop(t + dur + .05);
      }
      g.gain.setValueAtTime(.0001, t);
      g.gain.linearRampToValueAtTime(vol, t + .014);
      g.gain.setValueAtTime(vol * .9, t + dur * .55);
      g.gain.exponentialRampToValueAtTime(.0001, t + dur + .07);
      osc.connect(bp); bp.connect(g); g.connect(dest);
      osc.start(t); osc.stop(t + dur + .12);
    };
    canto(t0 + .00, { f0: 2350, f1: 3150, f2: 1950, dur: .27, vol: .32 });
    canto(t0 + .17, { f0: 3250, f1: 3650, f2: 3300, dur: .12, vol: .16 });
    canto(t0 + .32, { f0: 1900, f1: 2080, f2: 1960, dur: .36, trino: 135, vel: 33, vol: .28 });
    canto(t0 + .72, { f0: 2650, f1: 2080, f2: 2700, dur: .30, trino: 55, vel: 24, vol: .24 });
    canto(t0 + .98, { f0: 1520, f1: 1820, f2: 1460, dur: .22, vol: .13 });
    canto(t0 + 1.12, { f0: 3050, f1: 3400, f2: 2900, dur: .16, trino: 90, vel: 42, vol: .12 });
  },
  /* Hojas de libro. El barrido anterior sonaba a «swish» de sintetizador:
     al papel lo define el CRUJIDO, o sea ruido con microimpulsos irregulares.
     Por eso el sonido se construye muestra a muestra, y cada hoja cierra con
     el chasquido de soltarse. */
  hojas(ctx, dest, t0) {
    const papel = seg => {
      const sr = ctx.sampleRate, n = Math.floor(sr * seg);
      const b = ctx.createBuffer(1, n, sr), d = b.getChannelData(0);
      let env = 0, obj = 0;
      for (let i = 0; i < n; i++) {
        if (i % 210 === 0) obj = Math.random();           // el roce va cambiando
        env += (obj - env) * .0045;                        // suavizado del roce
        const p = i / n;
        const forma = Math.sin(Math.PI * Math.pow(p, .55));// ataque rápido, cola larga
        const chispa = Math.random() < .0016 ? (Math.random() * 2 - 1) * 3.2 : 0;
        d[i] = ((Math.random() * 2 - 1) * env * .85 + chispa) * forma * .5;
      }
      return b;
    };
    [0, .27, .52].forEach((d, i) => {
      const t = t0 + d;
      const s = ctx.createBufferSource(); s.buffer = papel(.44);
      s.playbackRate.value = .92 + i * .11;
      const hp = ctx.createBiquadFilter(); hp.type = "highpass"; hp.frequency.value = 620;
      const pk = ctx.createBiquadFilter(); pk.type = "peaking";
      pk.frequency.value = 2500 + i * 420; pk.gain.value = 7.5; pk.Q.value = .9;
      const g = ctx.createGain(); g.gain.value = .58 - i * .09;
      s.connect(hp); hp.connect(pk); pk.connect(g); g.connect(dest);
      s.start(t); s.stop(t + .5);

      const c = ctx.createBufferSource(); c.buffer = bufferRuido(ctx, .08);
      const cf = ctx.createBiquadFilter(); cf.type = "bandpass"; cf.Q.value = 1.7;
      cf.frequency.setValueAtTime(4400, t + .17);
      cf.frequency.exponentialRampToValueAtTime(1100, t + .25);
      const cg = ctx.createGain();
      cg.gain.setValueAtTime(.0001, t + .17);
      cg.gain.linearRampToValueAtTime(.34, t + .182);
      cg.gain.exponentialRampToValueAtTime(.0001, t + .27);
      c.connect(cf); cf.connect(cg); cg.connect(dest);
      c.start(t + .17); c.stop(t + .3);
    });
  },
  /* marimba de chonta: tres notas con brillo corto encima */
  marimba(ctx, dest, t0) {
    [523.25, 659.25, 783.99].forEach((f, i) => {
      const t = t0 + i * .13;
      const o = ctx.createOscillator(); o.type = "triangle"; o.frequency.value = f;
      const b = ctx.createOscillator(); b.type = "sine"; b.frequency.value = f * 4.1;
      const g = ctx.createGain(), gb = ctx.createGain();
      g.gain.setValueAtTime(.0001, t);
      g.gain.linearRampToValueAtTime(.40, t + .008);
      g.gain.exponentialRampToValueAtTime(.0001, t + .75);
      gb.gain.setValueAtTime(.0001, t);
      gb.gain.linearRampToValueAtTime(.10, t + .005);
      gb.gain.exponentialRampToValueAtTime(.0001, t + .15);
      o.connect(g); g.connect(dest); b.connect(gb); gb.connect(dest);
      o.start(t); o.stop(t + .85); b.start(t); b.stop(t + .2);
    });
  },
  /* ola rompiendo: ruido con el filtro cayendo */
  ola(ctx, dest, t0) {
    const s = ctx.createBufferSource(); s.buffer = bufferRuido(ctx, 1.8);
    const f = ctx.createBiquadFilter(); f.type = "lowpass";
    f.frequency.setValueAtTime(2800, t0);
    f.frequency.exponentialRampToValueAtTime(280, t0 + 1.1);
    const g = ctx.createGain();
    g.gain.setValueAtTime(.0001, t0);
    g.gain.linearRampToValueAtTime(.5, t0 + .2);
    g.gain.exponentialRampToValueAtTime(.0001, t0 + 1.35);
    s.connect(f); f.connect(g); g.connect(dest); s.start(t0); s.stop(t0 + 1.6);
  },
  /* gaviota sobre el mar: la ola y un graznido descendente */
  gaviota(ctx, dest, t0) {
    AVISOS.ola(ctx, dest, t0);
    [0, .30].forEach(d => {
      const t = t0 + .25 + d;
      const o = ctx.createOscillator(); o.type = "sawtooth";
      const f = ctx.createBiquadFilter(); f.type = "bandpass"; f.Q.value = 4;
      f.frequency.value = 1500;
      const g = ctx.createGain();
      o.frequency.setValueAtTime(1150, t);
      o.frequency.exponentialRampToValueAtTime(620, t + .28);
      g.gain.setValueAtTime(.0001, t);
      g.gain.linearRampToValueAtTime(.18, t + .04);
      g.gain.exponentialRampToValueAtTime(.0001, t + .32);
      o.connect(f); f.connect(g); g.connect(dest); o.start(t); o.stop(t + .4);
    });
  },
  /* campana suave: confirmación */
  campana(ctx, dest, t0) {
    [880, 1318.5].forEach((f, i) => {
      const t = t0 + i * .09;
      const o = ctx.createOscillator(); o.type = "sine"; o.frequency.value = f;
      const g = ctx.createGain();
      g.gain.setValueAtTime(.0001, t);
      g.gain.linearRampToValueAtTime(.30, t + .01);
      g.gain.exponentialRampToValueAtTime(.0001, t + 1.4);
      o.connect(g); g.connect(dest); o.start(t); o.stop(t + 1.5);
    });
  },
  /* madera: un golpe seco y grave */
  madera(ctx, dest, t0) {
    const o = ctx.createOscillator(); o.type = "triangle";
    o.frequency.setValueAtTime(220, t0);
    o.frequency.exponentialRampToValueAtTime(90, t0 + .18);
    const s = ctx.createBufferSource(); s.buffer = bufferRuido(ctx, .2);
    const f = ctx.createBiquadFilter(); f.type = "bandpass"; f.frequency.value = 1800; f.Q.value = 2;
    const g = ctx.createGain(), gs = ctx.createGain();
    g.gain.setValueAtTime(.0001, t0);
    g.gain.linearRampToValueAtTime(.45, t0 + .006);
    g.gain.exponentialRampToValueAtTime(.0001, t0 + .3);
    gs.gain.setValueAtTime(.0001, t0);
    gs.gain.linearRampToValueAtTime(.25, t0 + .004);
    gs.gain.exponentialRampToValueAtTime(.0001, t0 + .09);
    o.connect(g); g.connect(dest); s.connect(f); f.connect(gs); gs.connect(dest);
    o.start(t0); o.stop(t0 + .35); s.start(t0); s.stop(t0 + .2);
  },
};

function usePaisajeSonoro(activo, volumen = 22) {
  const nodo = useRef(null);
  const vivo = useRef(activo);
  const vol = useRef(volumen);
  vol.current = volumen;

  const crear = useCallback(() => {
    /* Si el contexto quedó cerrado (React en modo estricto monta, desmonta y
       vuelve a montar en desarrollo), hay que soltarlo y crear uno nuevo.
       Sin esto el audio muere en el arranque y no vuelve nunca. */
    if (nodo.current && nodo.current.ctx.state === "closed") nodo.current = null;
    if (nodo.current) return nodo.current;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    const ctx = new AC();

    const src = ctx.createBufferSource();
    src.buffer = bufferRuido(ctx, 5); src.loop = true;
    const grave = ctx.createBiquadFilter();
    grave.type = "lowpass"; grave.frequency.value = 430; grave.Q.value = .7;
    const espuma = ctx.createBiquadFilter();
    espuma.type = "bandpass"; espuma.frequency.value = 1500; espuma.Q.value = .6;
    const gEspuma = ctx.createGain(); gEspuma.gain.value = .30;
    const vaiven = ctx.createGain(); vaiven.gain.value = .55;
    const ola = ctx.createOscillator(); ola.type = "sine"; ola.frequency.value = .085;
    const olaG = ctx.createGain(); olaG.gain.value = .42;
    ola.connect(olaG); olaG.connect(vaiven.gain);
    const master = ctx.createGain(); master.gain.value = 0;
    src.connect(grave); grave.connect(vaiven);
    src.connect(espuma); espuma.connect(gEspuma); gEspuma.connect(vaiven);
    vaiven.connect(master); master.connect(ctx.destination);
    src.start(); ola.start();

    nodo.current = { ctx, master };
    return nodo.current;
  }, []);

  /* El navegador no deja sonar antes de un gesto. Como el sonido arranca
     encendido, esperamos el primer clic o tecla y ahí lo soltamos. */
  useEffect(() => {
    const soltar = () => {
      const n = nodo.current;
      if (!n || n.ctx.state === "closed") return;      // aún no hay motor: seguimos esperando
      n.ctx.resume().then(() => {
        window.removeEventListener("pointerdown", soltar);
        window.removeEventListener("keydown", soltar);
      }).catch(() => { /* el navegador aún no lo permite; reintentamos al próximo gesto */ });
    };
    window.addEventListener("pointerdown", soltar);
    window.addEventListener("keydown", soltar);
    return () => {
      window.removeEventListener("pointerdown", soltar);
      window.removeEventListener("keydown", soltar);
    };
  }, []);

  useEffect(() => {
    vivo.current = activo;
    if (!activo) {
      const n = nodo.current;
      if (n) {
        const t = n.ctx.currentTime;
        n.master.gain.cancelScheduledValues(t);
        n.master.gain.setTargetAtTime(0, t, .35);
        setTimeout(() => { if (!vivo.current && n.ctx.state === "running") n.ctx.suspend(); }, 1600);
      }
      return;
    }
    const n = crear();
    if (!n) return;
    if (n.ctx.state === "suspended") n.ctx.resume().catch(() => {});
    const t = n.ctx.currentTime;
    n.master.gain.cancelScheduledValues(t);
    n.master.gain.setTargetAtTime(volumen / 100, t, .9);
  }, [activo, volumen, crear]);

  useEffect(() => () => {
    vivo.current = false;
    const n = nodo.current;
    nodo.current = null;                     // el siguiente montaje crea uno limpio
    if (n) { try { n.ctx.close(); } catch (e) { /* ya cerrado */ } }
  }, []);

  /* Aviso de transición. Silencio si el sonido está apagado. */
  return useCallback(aviso => {
    if (!vivo.current) return;
    const n = crear();
    if (!n) return;
    if (n.ctx.state === "suspended") n.ctx.resume().catch(() => {});
    const g = n.ctx.createGain();
    g.gain.value = Math.min(.85, (vol.current / 100) * 2.3);
    g.connect(n.ctx.destination);
    (AVISOS[aviso] || AVISOS.ola)(n.ctx, g, n.ctx.currentTime + .03);
    setTimeout(() => { try { g.disconnect(); } catch (e) { /* ya suelto */ } }, 3500);
  }, [crear]);
}

/* ===================== CAMPOS DE IMAGEN Y VIDEO ==========================
   Cada hueco declara su código de inventario, su formato y su estado. Se ve
   como una lámina pegada al papel: borde grueso, esquina redonda, sombra
   plana. Cuando llegue el archivo real solo se reemplaza el relleno.        */
const FMT = {
  imagen: "Fotografía", video: "Video", audio: "Audio", "360": "Video 360°",
  pdf: "PDF", ar: "Interactivo AR", ilustracion: "Ilustración",
};
const EST = { listo: "ok", proceso: "proceso", pendiente: "pend" };

function CampoVacio({ fmt, code }) {
  return (
    <span className="campo-vacio" aria-hidden="true">
      <svg viewBox="0 0 64 64" width="56" height="56" fill="none"
        stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
        {fmt === "video" || fmt === "360" ? (
          <><rect x="6" y="14" width="52" height="36" rx="7" /><path d="M27 26l13 6-13 6z" /></>
        ) : fmt === "audio" ? (
          <><path d="M8 32h6l6-14 8 30 7-22 5 10h16" /></>
        ) : fmt === "pdf" ? (
          <><path d="M14 6h24l12 12v40H14z" /><path d="M38 6v12h12" /><path d="M24 38h16M24 46h10" /></>
        ) : fmt === "ar" ? (
          <><path d="M32 8l22 12v24L32 56 10 44V20z" /><path d="M32 32l22-12M32 32v24M32 32L10 20" /></>
        ) : (
          <><rect x="6" y="12" width="52" height="40" rx="7" /><circle cx="23" cy="27" r="5" />
            <path d="M12 48l16-14 10 9 7-6 9 8" /></>
        )}
      </svg>
      <span className="campo-t">{FMT[fmt]}</span>
      <span className="campo-c">{code}</span>
    </span>
  );
}

function Media({ code, fmt = "imagen", cap, est = "Por producir", fase = "pendiente",
  ratio = "16/9", onPlay, dur }) {
  const cl = !!onPlay;
  return (
    <figure className="media">
      <div className={"lamina" + (cl ? " es-click" : "")} style={{ aspectRatio: ratio }}
        onClick={onPlay} role={cl ? "button" : "img"} tabIndex={cl ? 0 : undefined}
        onKeyDown={e => cl && (e.key === "Enter" || e.key === " ") && (e.preventDefault(), onPlay(e))}
        aria-label={cap ? `${FMT[fmt]}: ${cap}` : FMT[fmt]}>
        <CampoVacio fmt={fmt} code={code} />
        {dur && <span className="dur">{dur}</span>}
        {cl && <span className="play" aria-hidden="true">
          <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor"
            strokeWidth="2.4" strokeLinejoin="round"><path d="M7 4l13 8-13 8z" /></svg>
        </span>}
      </div>
      {cap && <figcaption className="media-pie">
        <span>{cap}</span>
        <span className={"estado e-" + EST[fase]}>{est}</span>
      </figcaption>}
    </figure>
  );
}

/* Banner de cabecera: el campo de imagen grande con el titular encima */
function Banner({ code, fmt = "imagen", kicker, titulo, lede, cap, est = "Por producir",
  fase = "pendiente", accion, alto = "banner" }) {
  return (
    <header className={"banner " + alto}>
      <div className="banner-campo">
        <CampoVacio fmt={fmt} code={code} />
      </div>
      <div className="banner-txt">
        {kicker && <span className="eyebrow">{kicker}</span>}
        <h1 className="h1">{titulo}</h1>
        {lede && <p className="lede">{lede}</p>}
        {accion}
      </div>
      <span className="banner-tag">{cap || FMT[fmt]} · <b>{est}</b></span>
    </header>
  );
}

function Galeria({ base, n }) {
  return (
    <div className="grid-gal">
      {Array.from({ length: n }, (_, i) => (
        <Media key={i} code={`${base}.${i + 1}`} fmt="imagen" ratio="4/3"
          cap={`Foto ${i + 1} · alt descriptivo pendiente`}
          est="Por seleccionar" fase="proceso" />
      ))}
    </div>
  );
}

/* ===================== ADORNOS: separadores con marea e ilustración ======= */
function Ola({ inv }) {
  return (
    <svg className={"ola" + (inv ? " inv" : "")} viewBox="0 0 1440 60" preserveAspectRatio="none"
      aria-hidden="true">
      <path d="M0 34 C120 6 240 62 360 34 C480 6 600 62 720 34 C840 6 960 62 1080 34
        C1200 6 1320 62 1440 34 L1440 60 L0 60 Z" fill="currentColor" />
    </svg>
  );
}
function Separador({ il = "palma" }) {
  return (
    <div className="separador" aria-hidden="true">
      <span className="sep-linea" />
      <svg viewBox="-70 -70 140 140" width="52" height="52">
        {il === "palma" ? <IlPalma s={1.1} /> :
          il === "cangrejo" ? <g transform="scale(.75)"><IlCangrejo /></g> :
            il === "tortuga" ? <g transform="scale(.6)"><IlTortuga /></g> :
              <g transform="scale(.5) translate(0,20)"><IlCacao /></g>}
      </svg>
      <span className="sep-linea" />
    </div>
  );
}

/* Límites del encuadre: el lienzo nunca puede dejar hueco. Con zoom z, el
   desplazamiento admisible va de 1440(1-z) a 0 en x, y de 900(1-z) a 0 en y. */
function limitaVista(z, tx, ty) {
  const nz = Math.min(3, Math.max(1, z));
  return {
    z: nz,
    tx: Math.min(0, Math.max(1440 * (1 - nz), tx)),
    ty: Math.min(0, Math.max(900 * (1 - nz), ty)),
  };
}

/* ===================== MAPA VIVO =========================================
   La costa solo muestra los puntos: un medallón de retrato clavado en su
   lugar exacto. El nombre no vive en el mapa — aparece como globo flotante
   al señalar el punto, y desaparece al salir. Así el mapa respira.        */

function Rotulo({ label, x, y, chico }) {
  const w = (chico ? 12 : 16) + label.length * (chico ? 7.4 : 9.4);
  const h = chico ? 24 : 30;
  return (
    <g transform={`translate(${x},${y})`}>
      <rect x={-w / 2} y={-h / 2} width={w} height={h} rx={h / 2} className="rotulo-caja" />
      <text x="0" y={chico ? 4 : 5} textAnchor="middle"
        className={"rotulo-txt" + (chico ? " chico" : "")}>{label}</text>
    </g>
  );
}

/* El punto: el medallón se apoya sobre la costa y la punta marca el sitio */
function Punto({ x, y, code, activo, exp, onEnter, onLeave, onClick, etiqueta }) {
  return (
    <g className={"nodo-p" + (activo ? " on" : "")} transform={`translate(${x},${y})`}
      tabIndex={0} role="button" aria-label={etiqueta}
      onMouseEnter={onEnter} onMouseLeave={onLeave} onFocus={onEnter} onBlur={onLeave}
      onClick={onClick}
      onKeyDown={e => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), onClick())}>
      <circle cy="-30" r="44" fill="transparent" />
      <g className="med">
        <path d="M-9 -14 L9 -14 L0 0 Z" className="med-pin" />
        <circle cy="-40" r="30" className={"med-aro" + (exp ? " exp" : "")} />
        <circle cy="-40" r="23" className="med-foto" />
        <text y="-36" textAnchor="middle" className="med-img">{code}</text>
      </g>
      <circle r="4" className="med-punta" />
    </g>
  );
}

/* El globo: aparece al señalar un punto. Lleva el campo de imagen arriba y la
   ficha debajo, todo dentro de la misma tarjeta. Va contra-escalado (1/z) para
   que conserve su tamaño de lectura por más que se acerque el mapa. */
const G_W = 236, G_H = 202;

function Globo({ x, y, nombre, lugar, code, z, izq }) {
  const cx = izq ? -(G_W + 42) : 42;          // la tarjeta, al lado que tenga aire
  const cy = -(G_H + 26);
  const anclaX = izq ? cx + G_W - 14 : cx + 14;
  return (
    <g className="globo" pointerEvents="none"
      transform={`translate(${x},${y}) scale(${1 / z})`}>
      <path className="globo-hilo" d={`M${anclaX} ${cy + G_H} L${izq ? -13 : 13} -13`} />
      <g transform={`translate(${cx},${cy})`}>
        <rect x="0" y="0" width={G_W} height={G_H} rx="20" className="globo-caja" />

        {/* campo de imagen, dentro de la misma tarjeta */}
        <rect x="12" y="12" width={G_W - 24} height="108" rx="12" className="globo-foto" />
        <g transform={`translate(${G_W / 2 - 17},34)`} className="globo-ico">
          <rect x="0" y="0" width="34" height="26" rx="5" />
          <circle cx="10" cy="9" r="3.2" />
          <path d="M3 22 L13 13 L19 18 L24 14 L31 22 Z" />
        </g>
        <text x={G_W / 2} y="80" textAnchor="middle" className="globo-fmt">FOTOGRAFÍA</text>
        <rect x={G_W / 2 - 40} y="90" width="80" height="19" rx="9.5" className="globo-pill" />
        <text x={G_W / 2} y="103.5" textAnchor="middle" className="globo-pillt">{code}</text>

        {/* la ficha */}
        <text x="18" y="148" className="globo-nom">{nombre}</text>
        <text x="18" y="168" className="globo-lug">{lugar}</text>
        <text x="18" y="186" className="globo-code">{code}</text>
      </g>
    </g>
  );
}

function MapaVivo({ gran, vista, setVista, onNucleo, onSaber, onHover, activo, flotantes, onFicha }) {
  const [sobre, setSobre] = useState(null);
  const svgRef = useRef(null);
  const arrastre = useRef(null);
  const movio = useRef(false);
  const [arrastrando, setArrastrando] = useState(false);
  const { z, tx, ty } = vista;
  const t = gran ? "scale(.72) translate(200,150)" : `translate(${tx} ${ty}) scale(${z})`;

  /* punto del ratón en coordenadas del lienzo */
  const aLienzo = e => {
    const svg = svgRef.current;
    if (!svg || !svg.getScreenCTM) return null;
    const p = svg.createSVGPoint();
    p.x = e.clientX; p.y = e.clientY;
    const m = svg.getScreenCTM();
    return m ? p.matrixTransform(m.inverse()) : null;
  };

  const bajar = e => {
    if (gran || z <= 1) return;
    const u = aLienzo(e); if (!u) return;
    movio.current = false;
    arrastre.current = { ux: u.x, uy: u.y, tx, ty };
    setArrastrando(true);
    try { e.currentTarget.setPointerCapture(e.pointerId); } catch (err) { /* sin captura */ }
  };
  const mover = e => {
    const a = arrastre.current; if (!a) return;
    const u = aLienzo(e); if (!u) return;
    const dx = u.x - a.ux, dy = u.y - a.uy;
    if (Math.abs(dx) + Math.abs(dy) > 6) movio.current = true;
    setVista(v => limitaVista(v.z, a.tx + dx, a.ty + dy));
  };
  const soltar = () => { arrastre.current = null; setArrastrando(false); };

  /* rueda: acercar y alejar hacia donde está el cursor */
  useEffect(() => {
    const svg = svgRef.current; if (!svg) return;
    const rueda = e => {
      if (gran) return;
      e.preventDefault();
      const p = svg.createSVGPoint();
      p.x = e.clientX; p.y = e.clientY;
      const m = svg.getScreenCTM(); if (!m) return;
      const u = p.matrixTransform(m.inverse());
      setVista(v => {
        const nz = Math.min(3, Math.max(1, v.z * (e.deltaY < 0 ? 1.16 : 1 / 1.16)));
        const lx = (u.x - v.tx) / v.z, ly = (u.y - v.ty) / v.z;
        return limitaVista(nz, u.x - nz * lx, u.y - nz * ly);
      });
    };
    svg.addEventListener("wheel", rueda, { passive: false });
    return () => svg.removeEventListener("wheel", rueda);
  }, [gran, setVista]);

  const globo = (() => {
    if (!sobre) return null;
    if (sobre === EXPANSION.slug)
      return { x: 1392, y: 206, nombre: "Gente de Río", lugar: "Quibdó · fuera de Nuquí", code: "IMG-03.1" };
    const n = NUCLEOS.find(x => x.slug === sobre);
    if (!n) return null;
    const m = MAPA_N[n.corto1];
    return { x: m.punto[0], y: m.punto[1], nombre: n.corto1, lugar: m.lugar, code: n.retrato };
  })();

  return (
    <svg className="mapa" viewBox="0 0 1440 900" preserveAspectRatio="xMidYMid meet"
      ref={svgRef} data-mover={!gran && z > 1}
      onPointerDown={bajar} onPointerMove={mover} onPointerUp={soltar} onPointerCancel={soltar}
      onClickCapture={e => { if (movio.current) { e.stopPropagation(); movio.current = false; } }}
      role="img"
      aria-label="Mapa ilustrado del municipio de Nuquí, Chocó. Cada retrato clavado en la costa abre la historia de una persona.">
      <MapaDefs />
      <clipPath id="cn"><path d={INTER["Nuquí"]} /></clipPath>
      <rect width="1440" height="900" fill="#F7F2DE" />
      <g transform={t} style={{
        transition: arrastrando ? "none" : "transform .55s cubic-bezier(.3,.8,.2,1)"
      }}>
        {/* el desvanecido de acuarela del mapa impreso */}
        <ellipse cx="250" cy="300" rx="300" ry="240" fill="url(#washv)" />
        <ellipse cx="430" cy="640" rx="260" ry="190" fill="url(#washa)" />
        <IlOlas />

        {FONDO.map((d, i) => <path key={i} d={d} fill="#A9CE93" stroke="#fff" strokeWidth="4" />)}
        {Object.entries(INTER).map(([n, d]) => d && n !== "Nuquí" &&
          <path key={n} d={d} fill="#A9CE93" stroke="#fff" strokeWidth="4" />)}

        <path d={INTER["Nuquí"]} fill="none" stroke="#EDE7C4" strokeWidth="20" strokeLinejoin="round" />
        <path d={INTER["Nuquí"]} fill="#5CB747" stroke="#fff" strokeWidth="5" strokeLinejoin="round" />
        <g clipPath="url(#cn)">
          <rect x="700" y="100" width="700" height="800" fill="url(#grass)" />
          {CLAROS.map(([cx, cy, rx, ry], i) =>
            <ellipse key={i} cx={cx} cy={cy} rx={rx} ry={ry} fill="#B3DB8C" opacity=".6" />)}
          <IlRios />
        </g>

        <g transform="translate(1338,196)"><IlCacao /></g>
        <g transform="translate(1340,452) scale(.86)"><IlPava /></g>
        <g transform="translate(1180,250) scale(.45)"><IlPalapas /></g>
        <g transform="translate(960,786)"><IlPersona /></g>
        {PALMAS.map(([x, y, s, f], i) =>
          <g key={i} transform={`translate(${x},${y})`}><IlPalma s={s} flip={f} /></g>)}
        {NUBES.map(([x, y, s], i) =>
          <g key={i} transform={`translate(${x},${y})`} className={"fl fl-" + (i % 3 + 1)}>
            <IlNube s={s} /></g>)}

        <g transform="translate(300,690) scale(.8)" className="fl fl-2"><IlTortuga /></g>
        <g transform="translate(112,760) scale(.66)" className="fl fl-3"><IlCangrejo /></g>
        <g transform="translate(600,690) scale(.26)" className="fl fl-1"><IlBallena /></g>

        {/* rótulo: la ballena y las letras, como en el mapa impreso */}
        <g className="lockup" aria-hidden="true">
          <g transform="translate(120,150) scale(.86)"><IlBallena /></g>
          <text x="70" y="392" className="tit-nuqui" fill="url(#letraN)">Nuquí</text>
          <text x="212" y="452" className="tit-choco" fill="url(#letraC)">Chocó</text>
        </g>
        <text x="70" y="862" className="mar-txt">Océano Pacífico · Golfo de Tribugá</text>

        {PUEBLOS.map(([l, x, y]) => <g key={l} aria-hidden="true"><Rotulo label={l} x={x} y={y} /></g>)}

        {/* saberes: punto discreto, el nombre aparece al señalarlo */}
        {SABERES.map(s => {
          const [x, y] = MAPA_S[s.slug];
          return (
            <g key={s.slug} className="nodo-saber" transform={`translate(${x},${y})`}
              onMouseEnter={() => onHover({
                t: "Saber", n: s.nombre, pl: "Capa transversal del territorio",
                tx: s.def, go: "Abrir el saber", dest: ["saber", s.slug],
              })}
              onClick={() => onSaber(s.slug)} tabIndex={0} role="button"
              onKeyDown={e => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), onSaber(s.slug))}
              aria-label={`Saber: ${s.nombre}`}>
              <circle r="26" fill="transparent" />
              <circle r="14" className="saber-aro" />
              <circle r="6" className="saber-pt" />
              <g className="saber-rot"><Rotulo label={s.slug} x={0} y={-34} chico /></g>
            </g>
          );
        })}

        {/* las puertas: solo el punto sobre la costa */}
        {NUCLEOS.map(n => {
          const m = MAPA_N[n.corto1];
          return (
            <Punto key={n.slug} x={m.punto[0]} y={m.punto[1]} code="IMG"
              activo={activo === n.slug || sobre === n.slug}
              etiqueta={`${n.nombre}, ${n.lugar}. Eje: ${n.eje}. Abrir su historia.`}
              onEnter={() => {
                setSobre(n.slug);
                onHover({
                  t: `Eje: ${n.eje}`, n: n.nombre, pl: n.lugar, tx: n.frase,
                  go: "Entrar a la historia", dest: ["nucleo", n.slug], slug: n.slug,
                });
              }}
              onLeave={() => setSobre(s => s === n.slug ? null : s)}
              onClick={() => onNucleo(n.slug)} />
          );
        })}

        {gran && (
          <g className="entra">
            <Punto x={1392} y={206} code="IMG" exp
              activo={sobre === EXPANSION.slug}
              etiqueta="Gente de Río, Quibdó. Expansión del universo, fuera de Nuquí."
              onEnter={() => {
                setSobre(EXPANSION.slug);
                onHover({
                  t: "Expansión del universo", n: EXPANSION.nombre, pl: "Quibdó · fuera de Nuquí",
                  tx: EXPANSION.frase, go: "Ver la expansión", dest: ["nucleo", EXPANSION.slug],
                });
              }}
              onLeave={() => setSobre(s => s === EXPANSION.slug ? null : s)}
              onClick={() => onNucleo(EXPANSION.slug)} />
          </g>
        )}

        {flotantes && UGC.slice(0, 5).map((u, i) => {
          const p = [[960, 200], [1214, 640], [880, 480], [1000, 830], [1240, 760]][i];
          return (
            <g key={i} className="flot" transform={`translate(${p[0]},${p[1]})`}
              onClick={() => onFicha(i)} tabIndex={0} role="button"
              onKeyDown={e => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), onFicha(i))}
              aria-label={`Historia de la comunidad: ${u.t}, por ${u.a} en ${u.p}`}
              style={{ animation: `pop .5s ${i * .08}s cubic-bezier(.34,1.6,.5,1) backwards` }}>
              <rect x="-18" y="-23" width="36" height="46" rx="8" className="flot-caja" />
              <text x="0" y="5" textAnchor="middle" className="flot-txt">
                {u.tipo === "video" ? "▶" : u.tipo === "audio" ? "♪" : u.tipo === "foto" ? "◻" : "«»"}
              </text>
            </g>
          );
        })}

        {/* el globo va al final para quedar siempre por encima */}
        {globo && <Globo {...globo} z={gran ? .72 : z}
          izq={(globo.x * (gran ? .72 : z) + (gran ? 0 : tx)) > 620} />}
      </g>
    </svg>
  );
}

/* ===================== REPRODUCTOR (§5.1) ================================ */
function Reproductor({ corto, contexto, onGo, onFocus }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="player">
      <Media code={corto.code} fmt="video" ratio="16/9" dur={corto.dur}
        cap={`Corto documental · «${corto.titulo}»`}
        est="Grabado · en postproducción" fase="proceso"
        onPlay={e => onFocus(e, `Corto · ${corto.titulo}`)} />
      <div className="barra" aria-hidden="true">
        <span className="barra-via"><span className="barra-llena" /></span>
        <span className="barra-t">{corto.dur}</span>
      </div>
      <div className="tools">
        <span className="tool">CC · subtítulos ES/EN</span>
        <span className="tool">LSC · lengua de señas</span>
        <button className="tool tool-b" onClick={() => setOpen(o => !o)} aria-expanded={open}>
          {open ? "Ocultar transcripción" : "Leer transcripción"}
        </button>
      </div>
      {open && (
        <div className="transcript">
          <span className="chip">TXT · transcripción</span>
          <p>La transcripción completa va aquí, con marcas de tiempo y nombre de quien habla.
            Es requisito de accesibilidad (WCAG 2.1 AA) y además indexa el video para buscadores.</p>
        </div>
      )}
      <div className="ctx">
        <span className="eyebrow">Contexto del corto</span>
        <div className="ctx-grid">
          {contexto.map((c, i) => (
            <button key={i} className="ctx-card" onClick={() => onGo(...c.to)}>
              <span className="ctx-mini" aria-hidden="true">
                <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor"
                  strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                  <rect x="3" y="5" width="18" height="14" rx="3" /><circle cx="9" cy="11" r="2" />
                  <path d="M4 18l6-5 4 3.5 3-2.5 4 4" /></svg>
              </span>
              <span className="ctx-w">
                <span className="ctx-t">{c.t}</span>
                <span className="ctx-d">{c.d}</span>
              </span>
              <span className="flecha">→</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

/* ===================== HILOS (§5.2) ====================================== */
function Hilos({ items, onGo }) {
  return (
    <section className="hilos">
      <h2 className="h2">Los hilos del territorio</h2>
      <p className="sub">Estas historias no están sueltas: así se conectan en la vida real.</p>
      <div className="hilos-row">
        {items.slice(0, 3).map((h, i) => (
          <button key={i} className="hilo" onClick={() => onGo(...h.to)}>
            <span className="hilo-mini"><CampoVacio fmt="imagen" code="IMG" /></span>
            <span className="hilo-f">{h.f}</span>
            <span className="hilo-to">{h.l} <span className="flecha">→</span></span>
          </button>
        ))}
      </div>
    </section>
  );
}

/* ===================== NAVEGACIÓN Y PIEZAS SUELTAS ======================= */
function Migas({ trail, onGo }) {
  return (
    <nav className="migas" aria-label="Ubicación en el sitio">
      {trail.map((t, i) => (
        <span key={i}>
          {t.to ? <button className="miga-l" onClick={() => onGo(...t.to)}>{t.l}</button>
            : <span className="miga-n">{t.l}</span>}
          {i < trail.length - 1 && <span className="miga-s">→</span>}
        </span>
      ))}
    </nav>
  );
}

function MiniMapa({ slug, label }) {
  const xy = slug && MAPA_N[slug] ? MAPA_N[slug].punto : null;
  return (
    <div className="minimapa">
      <svg viewBox="940 100 420 780" aria-hidden="true">
        {FONDO.map((d, i) => <path key={i} d={d} fill="#C6DFB4" stroke="#fff" strokeWidth="4" />)}
        {Object.entries(INTER).map(([n, d]) => d && n !== "Nuquí" &&
          <path key={n} d={d} fill="#C6DFB4" stroke="#fff" strokeWidth="4" />)}
        <path d={INTER["Nuquí"]} fill="#5CB747" stroke="#fff" strokeWidth="6" />
        {xy && <>
          <circle cx={xy[0]} cy={xy[1]} r="46" fill="none" stroke="#E8603A" strokeWidth="9" opacity=".45" />
          <circle cx={xy[0]} cy={xy[1]} r="20" fill="#E8603A" stroke="#1B3A24" strokeWidth="5" />
        </>}
      </svg>
      <span className="minimapa-l">{label}</span>
    </div>
  );
}

function Head({ kicker, h, p }) {
  return (
    <div className="head">
      {kicker && <span className="eyebrow">{kicker}</span>}
      <h1 className="h1">{h}</h1>
      {p && <p className="lede">{p}</p>}
    </div>
  );
}
const Em = ({ children }) => <em className="em">{children}</em>;

function Zona({ className, style, onClick, label, children }) {
  return (
    <div className={className} style={style} role="button" tabIndex={0} aria-label={label}
      onClick={onClick}
      onKeyDown={e => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), onClick())}>
      {children}
    </div>
  );
}

function SelloSEO({ url, titulo, meta, datos }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="seo">
      <button className="seo-t" onClick={() => setOpen(o => !o)} aria-expanded={open}>
        <span className="chip">Nota de producción · SEO</span>
        <code>{url}</code><span className="flecha">{open ? "▲" : "▼"}</span>
      </button>
      {open && (
        <dl className="seo-d">
          <dt>Título ({titulo.length}/60)</dt><dd>{titulo}</dd>
          <dt>Meta descripción ({meta.length}/155)</dt><dd>{meta}</dd>
          <dt>Datos estructurados</dt><dd>{datos}</dd>
        </dl>
      )}
    </div>
  );
}

