/* ===================== ESTILOS ===========================================
   Sistema derivado del mapa ilustrado del cliente:
   · Color   crema de océano, verde de tierra, coral de rótulo, azul de cielo.
   · Trazo   todo lleva contorno grueso y sombra plana, como una calcomanía
             pegada sobre el papel. Nada de degradados ni sombras difusas.
   · Tipos   Baloo 2 para titulares (la letra gorda redonda de «Nuquí»),
             Caveat para los apuntes a mano («Chocó»), Space Mono para los
             rótulos del mapa y las etiquetas, Nunito para leer.
   · Motion  la marea: las transiciones entran y salen con borde de ola.
   ======================================================================== */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Caveat:wght@600;700&family=Space+Mono:wght@400;700&family=Nunito:ital,wght@0,400;0,600;0,700;1,400&display=swap');

/* La plantilla de Vite trae  body{display:flex;place-items:center}  y
   #root{max-width:1280px;margin:0 auto;padding:2rem;text-align:center}.
   Eso recortaba la app y descentraba las superposiciones. Lo anulamos aquí
   para que el componente funcione tal cual en cualquier proyecto. */
html,body{margin:0;padding:0;width:100%;min-height:100%;background:#F7F2DE}
body{display:block;place-items:normal;min-width:0;text-align:left}
#root{max-width:none;width:100%;margin:0;padding:0;display:block;text-align:left}

.tv{
 --paper:#F7F2DE; --paper2:#FFFDF2; --sand:#EDE7C4;
 --ink:#1B3A24; --ink2:#41684C;
 --green:#5CB747; --green-d:#3E8F32; --green-deep:#1C5A2B; --green-l:#B3DB8C;
 --coral:#E8603A; --coral-d:#B33C18; --coral-l:#F6C4B2;
 --sky:#8CC3DA; --sky-d:#3F7E9E; --cacao:#A8332A;
 --acc:var(--green-deep); --acc-b:var(--green-l);
 --bd:2.5px solid var(--ink);
 --sh:4px 5px 0 rgba(27,58,36,.16);
 --sh-h:7px 9px 0 rgba(27,58,36,.20);
 --disp:'Baloo 2',system-ui,sans-serif;
 --hand:'Caveat',cursive;
 --mono:'Space Mono',ui-monospace,monospace;
 --body:'Nunito',system-ui,-apple-system,sans-serif;
 background:var(--paper); color:var(--ink); font-family:var(--body);
 font-size:16px; line-height:1.6; min-height:100vh; width:100%; overflow-x:hidden;
 -webkit-font-smoothing:antialiased;
}
/* El mapa ocupa exactamente el alto libre de la primera pantalla. --navh lo
   mide el componente, así no dependemos de un número mágico. Debajo siguen
   el resto de bloques y el pie, a los que se llega bajando. */
.home{height:calc(100vh - var(--navh,72px));height:calc(100dvh - var(--navh,72px))}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;
 clip:rect(0 0 0 0);white-space:nowrap;border:0}
.tv *{box-sizing:border-box}
.tv[data-acc=coral]{--acc:var(--coral-d);--acc-b:var(--coral-l)}
.tv[data-acc=sky]{--acc:var(--sky-d);--acc-b:#C6E2ED}
.tv[data-acc=cacao]{--acc:var(--cacao);--acc-b:#EFC3B4}
.tv button{font-family:inherit;color:inherit;background:none;border:none;cursor:pointer}
.tv :focus-visible{outline:3px dashed var(--coral-d);outline-offset:3px;border-radius:4px}

/* --- tipografía --- */
.h1{font-family:var(--disp);font-weight:800;font-size:clamp(32px,4.4vw,58px);line-height:1.02;
 margin:0;letter-spacing:-.5px}
.h2{font-family:var(--disp);font-weight:700;font-size:clamp(24px,3vw,36px);line-height:1.08;margin:0}
.h3{font-family:var(--disp);font-weight:700;font-size:clamp(18px,2vw,23px);line-height:1.15;margin:0}
.em{font-family:var(--hand);font-style:normal;font-weight:700;color:var(--coral-d);
 font-size:1.18em;line-height:.9}
.eyebrow{display:inline-block;font-family:var(--mono);font-size:11px;font-weight:700;
 letter-spacing:2.4px;text-transform:uppercase;color:var(--acc)}
.lede{margin:14px 0 0;font-size:17px;color:var(--ink2);max-width:58ch}
.sub{margin:6px 0 0;font-size:14.5px;color:var(--ink2);max-width:62ch}
.flecha{color:var(--coral-d);font-weight:700}
.wrap{max-width:1160px;margin:0 auto;padding:0 4vw}
.view{padding:26px 0 64px;animation:sube .55s cubic-bezier(.2,.8,.2,1)}
.head{max-width:660px;margin:0 0 32px}
.rule{border:0;height:0;margin:46px 0}

/* --- chips y estados --- */
.chip{display:inline-block;font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:1.4px;
 text-transform:uppercase;padding:5px 10px;border:2px solid var(--ink);border-radius:999px;
 background:var(--paper2)}
.estado{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:1.2px;
 text-transform:uppercase;white-space:nowrap;padding:4px 9px;border-radius:999px;border:2px solid}
.e-pend{color:var(--coral-d);border-color:var(--coral-l);background:#FDEFE9}
.e-proceso{color:var(--sky-d);border-color:#C6E2ED;background:#EAF4F8}
.e-ok{color:var(--green-deep);border-color:var(--green-l);background:#EDF6E2}
.fase2{color:var(--coral-d);background:#FDEFE9;border-color:var(--coral-l)}

/* --- campo de imagen vacío --- */
.lamina{position:relative;display:flex;align-items:center;justify-content:center;overflow:hidden;
 border:var(--bd);border-radius:16px;background:var(--sand);box-shadow:var(--sh);
 background-image:repeating-linear-gradient(-45deg,rgba(27,58,36,.045) 0 10px,transparent 10px 20px)}
.lamina.es-click{cursor:pointer;transition:transform .25s,box-shadow .25s}
.lamina.es-click:hover{transform:translate(-2px,-3px);box-shadow:var(--sh-h)}
.campo-vacio{display:flex;flex-direction:column;align-items:center;gap:6px;color:var(--ink);
 opacity:.62;padding:10px;text-align:center}
.campo-t{font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:1.8px;text-transform:uppercase}
.campo-c{font-family:var(--mono);font-size:11.5px;font-weight:700;color:var(--coral-d);
 background:var(--paper2);border:2px solid var(--ink);border-radius:999px;padding:2px 9px}
.dur{position:absolute;bottom:10px;right:10px;font-family:var(--mono);font-size:11px;font-weight:700;
 background:var(--ink);color:var(--paper);padding:3px 8px;border-radius:999px}
.play{position:absolute;width:62px;height:62px;border-radius:50%;border:var(--bd);
 background:var(--paper2);color:var(--ink);display:flex;align-items:center;justify-content:center;
 box-shadow:var(--sh)}
.media{margin:0}
.media-pie{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;
 padding:9px 4px 0;font-size:12.5px;color:var(--ink2)}
.grid-gal{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:14px}

/* --- banner de cabecera --- */
.banner{position:relative;display:flex;align-items:flex-end;border:var(--bd);
 border-radius:24px;overflow:hidden;box-shadow:var(--sh);background:var(--sand);
 margin-bottom:30px;padding:clamp(16px,2.4vw,26px);min-height:300px;
 background-image:
  radial-gradient(62% 84% at 76% 26%,rgba(143,203,106,.38),rgba(143,203,106,0) 70%),
  radial-gradient(54% 74% at 22% 78%,rgba(140,195,218,.30),rgba(140,195,218,0) 72%),
  repeating-linear-gradient(-45deg,rgba(27,58,36,.05) 0 12px,transparent 12px 24px)}
.banner.alto{min-height:380px}
.banner-campo{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
 pointer-events:none}
.banner-txt{position:relative;max-width:min(640px,100%);background:var(--paper2);
 border:var(--bd);border-radius:20px;box-shadow:var(--sh);padding:clamp(20px,2.8vw,30px);
 color:var(--ink)}
.banner-txt .h1{color:var(--ink);margin:0}
.banner-txt .lede{color:var(--ink2);font-size:16px;margin-top:12px}
.banner-txt .eyebrow{background:var(--ink);color:var(--paper);padding:7px 13px;
 border-radius:999px;margin-bottom:14px}
.banner-tag{position:absolute;top:14px;right:14px;font-family:var(--mono);font-size:10px;
 font-weight:700;letter-spacing:1.2px;text-transform:uppercase;background:var(--paper2);
 border:2px solid var(--ink);border-radius:999px;padding:5px 11px}

/* --- botones --- */
.cta{display:inline-flex;align-items:center;justify-content:space-between;gap:14px;width:100%;
 max-width:420px;padding:14px 20px;border:var(--bd);border-radius:999px;background:var(--green-deep);
 color:var(--paper);font-family:var(--mono);font-size:12px;font-weight:700;letter-spacing:1.6px;
 text-transform:uppercase;min-height:52px;box-shadow:var(--sh);
 transition:transform .2s,box-shadow .2s}
.cta:hover{transform:translate(-2px,-3px);box-shadow:var(--sh-h)}
.cta .flecha{color:var(--green-l)}
.cta-2{background:var(--paper2);color:var(--ink)}
.cta-2 .flecha{color:var(--coral-d)}

/* --- tarjetas --- */
.card{border:var(--bd);border-radius:18px;background:var(--paper2);padding:20px;
 box-shadow:var(--sh);text-align:left}
.card[role=button]{cursor:pointer;transition:transform .25s,box-shadow .25s}
.card[role=button]:hover{transform:translate(-2px,-4px);box-shadow:var(--sh-h)}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:18px}
.card .lamina{border-radius:14px 14px 0 0;border:0;border-bottom:var(--bd);box-shadow:none;margin:-20px -20px 16px}
.card.p0{padding:0;overflow:hidden}
.card.p0 .lamina{margin:0;border-radius:0;box-shadow:none;border:0;border-bottom:var(--bd)}
.card.p0 .media-pie{padding:0 16px}
.card-cuerpo{padding:16px 18px 18px}

/* --- reproductor --- */
.player{max-width:900px}
.barra{display:flex;align-items:center;gap:14px;margin-top:12px;padding:11px 16px;
 border:var(--bd);border-radius:999px;background:var(--paper2)}
.barra-via{flex:1;height:6px;border-radius:999px;background:var(--sand);position:relative;
 border:1.5px solid var(--ink)}
.barra-llena{position:absolute;inset:-1.5px 62% -1.5px -1.5px;background:var(--coral);
 border:1.5px solid var(--ink);border-radius:999px}
.barra-t{font-family:var(--mono);font-size:11.5px;font-weight:700}
.tools{display:flex;flex-wrap:wrap;gap:9px;margin-top:12px}
.tool{font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:1.4px;
 text-transform:uppercase;border:2px solid var(--ink);border-radius:999px;padding:8px 13px;
 background:var(--paper2)}
.tool-b{cursor:pointer;transition:background .2s}
.tool-b:hover{background:var(--green-l)}
.transcript{margin-top:14px;padding:16px 18px;border:2.5px dashed var(--ink2);border-radius:16px}
.transcript p{margin:10px 0 0;font-size:14px;color:var(--ink2)}
.ctx{margin-top:30px}
.ctx-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px;margin-top:14px}
.ctx-card{display:flex;align-items:center;gap:14px;text-align:left;padding:14px 16px;
 border:var(--bd);border-radius:16px;background:var(--paper2);box-shadow:var(--sh);
 transition:transform .22s,box-shadow .22s}
.ctx-card:hover{transform:translate(-2px,-3px);box-shadow:var(--sh-h)}
.ctx-mini{flex:0 0 42px;height:42px;display:flex;align-items:center;justify-content:center;
 border:2px solid var(--ink);border-radius:11px;background:var(--sand);color:var(--ink)}
.ctx-w{flex:1}
.ctx-t{display:block;font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:1.6px;
 text-transform:uppercase;color:var(--acc)}
.ctx-d{display:block;font-size:14.5px;font-weight:600;margin-top:2px}

/* --- hilos --- */
.hilos-row{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:20px}
.hilo{display:flex;flex-direction:column;gap:12px;text-align:left;padding:18px;
 border:var(--bd);border-radius:18px;background:var(--paper2);box-shadow:var(--sh);
 transition:transform .25s,box-shadow .25s}
.hilo:hover{transform:translate(-2px,-4px);box-shadow:var(--sh-h)}
.hilo-mini{height:86px;display:flex;align-items:center;justify-content:center;border:2px solid var(--ink);
 border-radius:12px;background:var(--sand)}
.hilo-mini .campo-vacio svg{width:30px;height:30px}
.hilo-mini .campo-t{display:none}
.hilo-f{font-size:14.5px;color:var(--ink);line-height:1.45}
.hilo-to{font-family:var(--mono);font-size:11px;font-weight:700;letter-spacing:1.4px;
 text-transform:uppercase;color:var(--acc);margin-top:auto}

/* --- migas, minimapa, seo --- */
.migas{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin-bottom:22px;
 font-family:var(--mono);font-size:11.5px;font-weight:700;letter-spacing:1.2px}
.miga-l{color:var(--ink2)}.miga-l:hover{color:var(--coral-d)}
.miga-n{color:var(--ink)}.miga-s{color:var(--ink2);opacity:.5}
.minimapa{display:flex;align-items:center;gap:14px;flex:0 0 auto}
.minimapa svg{width:96px;height:150px;border:var(--bd);border-radius:14px;background:var(--paper);
 box-shadow:var(--sh)}
.minimapa-l{font-family:var(--mono);font-size:11px;font-weight:700;letter-spacing:1.4px;
 text-transform:uppercase;color:var(--ink2);max-width:110px}
.seo{margin-top:40px;border:2.5px dashed var(--ink2);border-radius:16px}
.seo-t{display:flex;align-items:center;gap:12px;width:100%;padding:11px 14px;text-align:left;flex-wrap:wrap}
.seo-t code{font-family:var(--mono);font-size:12px;color:var(--ink2)}
.seo-d{margin:0;padding:0 14px 14px;display:grid;grid-template-columns:auto 1fr;gap:7px 16px}
.seo-d dt{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:1.4px;
 text-transform:uppercase;color:var(--acc);white-space:nowrap}
.seo-d dd{margin:0;font-size:13.5px;color:var(--ink2)}

/* --- separadores con ilustración --- */
.separador{display:flex;align-items:center;gap:18px;margin:46px 0;color:var(--green-deep)}
.sep-linea{flex:1;height:3px;border-radius:2px;
 background:repeating-linear-gradient(90deg,var(--green-deep) 0 14px,transparent 14px 24px)}
.ola{display:block;width:100%;height:44px}
.ola.inv{transform:scaleY(-1)}

/* --- barra superior --- */
.nav{position:sticky;top:0;z-index:80;display:flex;align-items:center;gap:20px;
 padding:12px 4vw;background:var(--paper);border-bottom:var(--bd)}
.marca{display:flex;flex-direction:column;align-items:flex-start;margin-right:auto;line-height:1}
.marca-n{font-family:var(--disp);font-weight:800;font-size:21px}
.marca-s{font-family:var(--hand);font-weight:700;font-size:17px;color:var(--coral-d);margin-top:-3px}
.navlinks{display:flex;gap:8px}
.navlink{font-family:var(--mono);font-size:11.5px;font-weight:700;letter-spacing:1.4px;
 text-transform:uppercase;padding:9px 13px;border-radius:999px;border:2px solid transparent;
 transition:background .2s,border-color .2s}
.navlink:hover{background:var(--green-l)}
.navlink[aria-current=page]{border-color:var(--ink);background:var(--paper2)}
.sonido{display:flex;align-items:center;gap:8px;font-family:var(--mono);font-size:10.5px;
 font-weight:700;letter-spacing:1.4px;text-transform:uppercase;border:var(--bd);border-radius:999px;
 padding:8px 13px;background:var(--paper2);min-height:42px}
.sonido[data-on=true]{background:var(--green-l)}
.audio{display:flex;align-items:center}
.vol{display:flex;align-items:center;gap:9px;border:var(--bd);border-radius:999px;
 background:var(--paper2);padding:8px 14px;min-height:42px;margin-left:10px;overflow:hidden;
 transition:opacity .3s ease,max-width .4s cubic-bezier(.3,.9,.2,1),
  padding .4s,margin-left .4s,border-color .3s}
.vol[data-ver=true]{opacity:1;max-width:210px}
.vol[data-ver=false]{opacity:0;max-width:0;padding-left:0;padding-right:0;margin-left:0;
 border-color:transparent;pointer-events:none}
.vol span{font-family:var(--mono);font-size:9.5px;font-weight:700;letter-spacing:1.2px;
 color:var(--ink2)}
.vol input[type=range]{-webkit-appearance:none;appearance:none;width:96px;height:8px;
 border:2px solid var(--ink);border-radius:999px;background:var(--sand);cursor:pointer}
.vol input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;
 width:20px;height:20px;border-radius:50%;background:var(--coral);
 border:2.5px solid var(--ink);box-shadow:2px 2px 0 rgba(27,58,36,.2);cursor:pointer}
.vol input[type=range]::-moz-range-thumb{width:18px;height:18px;border-radius:50%;
 background:var(--coral);border:2.5px solid var(--ink);cursor:pointer}
@media (max-width:1100px){.vol{display:none}}

/* --- barra inferior móvil --- */
.bottom{display:none}
.bottom-btn{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;
 min-height:58px;min-width:44px;color:var(--ink2);font-family:var(--mono);font-size:9.5px;
 font-weight:700;letter-spacing:.6px;text-transform:uppercase}
.bottom-btn[aria-current=page]{color:var(--coral-d)}

/* --- HOME: el mapa es el lienzo --- */
.home{display:grid;grid-template-columns:1fr 372px;
 transition:grid-template-columns .45s cubic-bezier(.3,.9,.2,1)}
.home[data-panel=cerrado]{grid-template-columns:1fr 0}
.mapa-wrap{position:relative;overflow:hidden;min-height:0;background:var(--paper);border-right:var(--bd)}
.home[data-panel=cerrado] .mapa-wrap{border-right:0}
/* pestaña para volver a sacar la ficha cuando está guardada */
.panel-tab{position:absolute;top:50%;right:0;transform:translateY(-50%);z-index:30;
 writing-mode:vertical-rl;border:var(--bd);border-right:0;border-radius:16px 0 0 16px;
 background:var(--paper2);padding:18px 10px;font-family:var(--mono);font-size:10.5px;
 font-weight:700;letter-spacing:1.8px;text-transform:uppercase;box-shadow:var(--sh)}
.panel-tab:hover{background:var(--green-l)}
.panel-cab{display:flex;align-items:center;justify-content:space-between;gap:12px;
 padding:12px 16px 12px 22px;border-bottom:2.5px solid var(--ink);background:var(--sand)}
.panel-cab span{font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:1.8px;
 text-transform:uppercase;color:var(--ink2)}
.guardar{border:2px solid var(--ink);border-radius:999px;background:var(--paper2);
 padding:7px 13px;font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:1.2px;
 text-transform:uppercase;min-height:38px}
.guardar:hover{background:var(--green-l)}
.mapa{position:absolute;inset:0;width:100%;height:100%}
.mar-txt{font-family:var(--hand);font-weight:700;font-size:34px;fill:#3F7E9E;opacity:.8}
.tit-nuqui{font-family:var(--disp);font-size:112px;font-weight:800;
 stroke:#fff;stroke-width:9;paint-order:stroke;letter-spacing:-2px}
.tit-choco{font-family:var(--hand);font-size:66px;font-weight:700;
 stroke:#fff;stroke-width:7;paint-order:stroke}
.rotulo-caja{fill:#fff;stroke:#1B3A24;stroke-width:2.4}
.rotulo-txt{font-family:var(--mono);font-size:16px;font-weight:700;fill:#1B3A24}
.rotulo-txt.chico{font-size:13px}
.nodo-saber{cursor:pointer}
.saber-aro{fill:#fff;stroke:#1B3A24;stroke-width:2.6;transition:fill .25s}
.saber-pt{fill:#E8603A;transition:r .25s}
.nodo-saber:hover .saber-aro,.nodo-saber:focus-visible .saber-aro{fill:#B3DB8C}
.nodo-saber:hover .saber-pt{r:9}
.saber-rot{opacity:0;transition:opacity .2s}
.nodo-saber:hover .saber-rot,.nodo-saber:focus-visible .saber-rot{opacity:1}
/* medallón clavado en la costa + globo que aparece al señalar */
.nodo-p{cursor:pointer}
.med{transition:transform .25s cubic-bezier(.34,1.5,.6,1)}
.nodo-p:hover .med,.nodo-p:focus-visible .med{transform:translateY(-7px)}
.med-aro{fill:#fff;stroke:#1B3A24;stroke-width:3;transition:stroke .2s,stroke-width .2s}
.med-aro.exp{stroke-dasharray:9 7}
.med-foto{fill:#EDE7C4;stroke:#1B3A24;stroke-width:1.8}
.med-img{font-family:var(--mono);font-size:11px;font-weight:700;fill:#B33C18}
.med-pin{fill:#E8603A;stroke:#1B3A24;stroke-width:2;stroke-linejoin:round}
.med-punta{fill:#1B3A24}
.nodo-p:hover .med-aro,.nodo-p:focus-visible .med-aro,.nodo-p.on .med-aro{stroke:#B33C18;stroke-width:4.5}
.globo{animation:globo .2s ease-out}
@keyframes globo{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:none}}
.globo-caja{fill:#fff;stroke:#1B3A24;stroke-width:2.8}
.globo-foto{fill:#EDE7C4;stroke:#1B3A24;stroke-width:2;stroke-dasharray:7 6}
.globo-ico{fill:none;stroke:#41684C;stroke-width:2.2;stroke-linejoin:round;stroke-linecap:round}
.globo-fmt{font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:1.8px;fill:#41684C}
.globo-pill{fill:#fff;stroke:#1B3A24;stroke-width:2}
.globo-pillt{font-family:var(--mono);font-size:10.5px;font-weight:700;fill:#B33C18}
.mapa[data-mover=true]{cursor:grab;touch-action:none}
.mapa[data-mover=true]:active{cursor:grabbing}
.globo-nom{font-family:var(--mono);font-size:17px;font-weight:700;fill:#1B3A24}
.globo-lug{font-family:var(--mono);font-size:12.5px;fill:#41684C}
.globo-code{font-family:var(--mono);font-size:10.5px;font-weight:700;fill:#B33C18}
.globo-hilo{fill:none;stroke:#B33C18;stroke-width:2.4;stroke-dasharray:5 5}
.flot-caja{fill:#FFFDF2;stroke:#B33C18;stroke-width:2.6}
.flot{cursor:pointer}
.flot:hover .flot-caja{fill:#F6C4B2}
.flot-txt{font-family:var(--mono);font-size:15px;font-weight:700;fill:#B33C18}
.fl{animation:flota 7s ease-in-out infinite}
.fl-2{animation-duration:9s;animation-delay:-2s}
.fl-3{animation-duration:11s;animation-delay:-4s}

.mapa-ctrl{position:absolute;right:18px;top:18px;z-index:25;display:flex;flex-direction:column;
 gap:10px;align-items:flex-end}
.ctrl-b{border:var(--bd);border-radius:999px;background:var(--paper2);padding:9px 14px;
 font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:1.4px;text-transform:uppercase;
 min-height:42px;box-shadow:var(--sh);transition:transform .2s,background .2s}
.ctrl-b:hover{transform:translate(-1px,-2px);background:var(--green-l)}
.ctrl-b[data-on=true]{background:var(--green-l)}
.ctrl-b.coral[data-on=true]{background:var(--coral-l)}
.zoom{display:flex;flex-direction:column;border:var(--bd);border-radius:999px;overflow:hidden;
 background:var(--paper2);box-shadow:var(--sh)}
.zoom button{width:42px;height:42px;font-family:var(--disp);font-size:20px;font-weight:700}
.zoom button:first-child{border-bottom:2px solid var(--ink)}
.zoom button:hover{background:var(--green-l)}
.mapa-pie{position:absolute;left:3.5%;bottom:16px;z-index:20;font-family:var(--mono);font-size:11px;
 font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:var(--ink2);
 background:var(--paper2);border:2px solid var(--ink);border-radius:999px;padding:6px 13px}
.inset{position:absolute;right:18px;bottom:16px;z-index:20;text-align:right;pointer-events:none}
.inset svg{width:104px;background:var(--paper2);border:var(--bd);border-radius:14px;padding:6px;
 box-shadow:var(--sh)}
.inset-l{display:block;margin-top:6px;font-family:var(--mono);font-size:9.5px;font-weight:700;
 letter-spacing:1.4px;text-transform:uppercase;color:var(--ink2)}

/* --- panel lateral / hoja inferior --- */
.panel{background:var(--paper2);overflow-y:auto;min-height:0;
 transition:opacity .3s}
.home[data-panel=cerrado] .panel{opacity:0;visibility:hidden;overflow:hidden}
.panel-b{padding:20px 22px;border-bottom:2.5px solid var(--ink)}
.panel-b:last-child{border-bottom:0}
.tirador{display:none}
.info-n{font-family:var(--disp);font-weight:700;font-size:24px;line-height:1.1;margin:6px 0 2px}
.info-p{font-size:14.5px;color:var(--ink2);margin:8px 0 0}
.brujula{display:flex;gap:6px;margin:12px 0 10px}
.brujula i{flex:1;height:12px;border:2px solid var(--ink);border-radius:999px;background:var(--sand)}
.brujula i[data-on=true]{background:var(--coral)}

/* --- listas --- */
.lista{display:grid;gap:14px}
.lista-item{display:grid;grid-template-columns:104px 1fr auto;gap:20px;align-items:center;
 padding:16px;border:var(--bd);border-radius:18px;background:var(--paper2);box-shadow:var(--sh);
 text-align:left;transition:transform .25s,box-shadow .25s}
.lista-item:hover{transform:translate(-2px,-4px);box-shadow:var(--sh-h)}
.li-foto{width:104px;height:104px;border-radius:50%;border:var(--bd);background:var(--sand);
 display:flex;align-items:center;justify-content:center;overflow:hidden}
.li-foto .campo-t{display:none}
.li-foto .campo-vacio svg{width:26px;height:26px}
.li-n{display:block;font-family:var(--disp);font-weight:700;font-size:24px;margin:4px 0 4px}
.li-f{display:block;font-size:14.5px;color:var(--ink2);max-width:56ch}

/* --- bloques --- */
.duo{display:grid;grid-template-columns:1fr 1fr;gap:clamp(24px,4vw,52px);align-items:center}
.num-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}
.num-item{display:flex;gap:14px;align-items:flex-start;padding:16px 18px;border:var(--bd);
 border-radius:16px;background:var(--paper2);box-shadow:var(--sh)}
.num-i{flex:0 0 34px;height:34px;border-radius:50%;background:var(--green-l);border:2px solid var(--ink);
 display:flex;align-items:center;justify-content:center;font-family:var(--disp);font-weight:700;font-size:16px}
.num-t{font-size:14.5px}

/* --- archivo vivo --- */
.convoca{border:var(--bd);border-radius:20px;background:var(--coral-l);padding:22px 24px;
 display:flex;flex-wrap:wrap;gap:20px;align-items:center;justify-content:space-between;
 box-shadow:var(--sh);margin-bottom:30px}
.filtros{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:22px}
.filtro{font-family:var(--mono);font-size:11px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;
 padding:10px 15px;border:var(--bd);border-radius:999px;background:var(--paper2);min-height:42px}
.filtro:hover{background:var(--green-l)}
.filtro[aria-pressed=true]{background:var(--ink);color:var(--paper)}
.ugc-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:18px}
.ugc{border:var(--bd);border-radius:18px;background:var(--paper2);overflow:hidden;text-align:left;
 box-shadow:var(--sh);transition:transform .25s,box-shadow .25s}
.ugc:hover{transform:translate(-2px,-4px);box-shadow:var(--sh-h)}
.ugc-media{aspect-ratio:1;position:relative;display:flex;align-items:center;justify-content:center;
 background:var(--sand);border-bottom:var(--bd)}
.ugc-pie{display:block;padding:14px 16px}
.ugc-t{display:block;font-size:15px;font-weight:700;line-height:1.35}
.ugc-meta{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:8px;
 font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.8px;color:var(--ink2)}
.pin{color:var(--coral-d)}
.onda{display:flex;align-items:flex-end;gap:3px;height:44px}
.onda i{width:4px;border-radius:2px;background:var(--coral)}

/* --- formularios --- */
.form{max-width:580px;display:grid;gap:20px}
.field{display:grid;gap:7px}
.label{font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:1.6px;
 text-transform:uppercase;color:var(--acc)}
.input,.select,.textarea{font-family:var(--body);font-size:15px;padding:13px 15px;min-height:50px;
 width:100%;border:var(--bd);border-radius:14px;background:var(--paper2);color:var(--ink)}
.textarea{min-height:110px;resize:vertical}
.hint{font-size:13px;color:var(--ink2)}
.radios{display:flex;flex-wrap:wrap;gap:9px}
.radio{font-family:var(--mono);font-size:11px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;
 padding:11px 16px;border:var(--bd);border-radius:999px;background:var(--paper2);min-height:46px}
.radio[aria-pressed=true]{background:var(--ink);color:var(--paper)}
.drop{border:2.5px dashed var(--ink2);border-radius:16px;padding:28px;text-align:center;
 font-size:14px;color:var(--ink2)}
.check{display:flex;gap:14px;align-items:flex-start;text-align:left;font-size:14px;line-height:1.5}
.check .box{flex:0 0 26px;height:26px;border:var(--bd);border-radius:8px;background:var(--paper2);
 display:flex;align-items:center;justify-content:center;font-weight:700;margin-top:1px}
.check[aria-pressed=true] .box{background:var(--green-l)}
.ok{border:var(--bd);border-radius:18px;background:#EDF6E2;padding:20px 22px;box-shadow:var(--sh)}

/* --- bajo el mapa, en la portada --- */
.baja{position:absolute;left:50%;bottom:14px;transform:translateX(-50%);z-index:20;
 display:flex;align-items:center;gap:9px;border:var(--bd);border-radius:999px;
 background:var(--paper2);padding:9px 16px;font-family:var(--mono);font-size:10.5px;
 font-weight:700;letter-spacing:1.6px;text-transform:uppercase;box-shadow:var(--sh);
 animation:respira 2.6s ease-in-out infinite}
.baja:hover{background:var(--green-l)}
@keyframes respira{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(4px)}}
.home-abajo{padding:56px 4vw 20px;max-width:1160px;margin:0 auto}
/* mismo desvanecido de acuarela detrás de los encabezados de sección */
.wash{position:relative}
.wash::before{content:"";position:absolute;left:-6%;right:-6%;top:-40px;height:260px;z-index:-1;
 pointer-events:none;border-radius:50%;
 background:
  radial-gradient(50% 60% at 30% 45%,rgba(143,203,106,.32),rgba(143,203,106,0) 72%),
  radial-gradient(45% 55% at 72% 55%,rgba(140,195,218,.26),rgba(140,195,218,0) 74%)}
.home-abajo .cards{margin-top:24px}
.principio{display:flex;flex-direction:column;gap:14px}
.principio svg{flex:0 0 auto}
.principio-il{width:64px;height:64px;border:var(--bd);border-radius:18px;background:var(--sand);
 display:flex;align-items:center;justify-content:center;box-shadow:var(--sh)}

/* --- pie --- */
.foot{margin-top:36px;color:var(--paper)}
.foot .ola{color:var(--green-deep);margin-bottom:-1px}
.foot-in,.foot-legal{background:var(--green-deep)}
.foot-in{padding:16px 4vw 44px;display:grid;grid-template-columns:320px 1fr;gap:46px;
 max-width:none}
.foot-marca{display:block;font-family:var(--disp);font-weight:800;font-size:26px}
.foot-script{display:block;font-family:var(--hand);font-weight:700;font-size:22px;color:var(--green-l);
 margin-top:-4px}
.foot-p{font-size:14px;color:#D8EBC8;margin:12px 0 0;max-width:44ch}
.foot-il{margin-top:10px;opacity:.9}
.foot-cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:28px}
.foot-k{display:block;font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:2px;
 text-transform:uppercase;color:var(--green-l);margin-bottom:12px}
.foot-l{display:block;font-size:14px;color:var(--paper);padding:5px 0;text-align:left}
.foot-l:hover{color:var(--green-l)}
.foot-s{display:block;font-size:13.5px;color:#D8EBC8;padding:4px 0}
.logos{display:flex;flex-wrap:wrap;gap:7px}
.logo-slot{font-family:var(--mono);font-size:9px;font-weight:700;color:var(--green-l);
 border:2px solid var(--green-l);border-radius:10px;padding:10px 8px}
.foot-legal{padding:0 4vw 26px;font-family:var(--mono);font-size:11px;color:#B9D8A4;
 display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px}

/* --- superposiciones --- */
.marea{position:fixed;top:0;left:0;right:0;bottom:0;width:100%;height:100%;z-index:200;
 pointer-events:none;animation:marea 1.05s cubic-bezier(.65,0,.35,1) forwards}
.marea-agua{position:absolute;inset:0;background:var(--green-deep)}
.marea-ola{position:absolute;left:0;right:0;top:-42px;height:44px;color:var(--green-deep);
 transform:scaleY(-1)}
.marea-txt{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
 width:min(88vw,780px);text-align:center;color:var(--paper)}
.marea-txt b{display:block;font-family:var(--disp);font-weight:800;
 font-size:clamp(28px,4.4vw,50px);line-height:1.1}
.marea-txt i{display:block;font-family:var(--hand);font-style:normal;font-weight:700;font-size:24px;
 color:var(--green-l)}
.scrim{position:fixed;inset:0;z-index:150;background:rgba(27,58,36,.5)}
.modal{position:fixed;z-index:160;top:50%;left:50%;transform:translate(-50%,-50%);
 width:min(94vw,760px);max-height:88vh;overflow-y:auto;background:var(--paper);border:var(--bd);
 border-radius:24px;padding:30px;box-shadow:8px 10px 0 rgba(27,58,36,.3);animation:pop .4s cubic-bezier(.34,1.5,.6,1)}
.modal-x{position:absolute;top:16px;right:16px;width:46px;height:46px;border:var(--bd);
 border-radius:50%;background:var(--paper2);font-size:18px;font-weight:700;box-shadow:var(--sh)}
.modal-x:hover{background:var(--coral-l)}
.ficha{position:fixed;z-index:160;top:50%;left:50%;transform:translate(-50%,-50%);
 width:min(94vw,430px);background:var(--paper);border:var(--bd);border-radius:24px;overflow:hidden;
 box-shadow:8px 10px 0 rgba(27,58,36,.3);animation:pop .38s cubic-bezier(.34,1.5,.6,1)}
.ficha-nav{display:flex;justify-content:space-between;border-top:var(--bd)}
.ficha-nav button{padding:14px;font-family:var(--mono);font-size:11px;font-weight:700;
 letter-spacing:1.2px;text-transform:uppercase;min-height:48px}
.ficha-nav button:hover{background:var(--green-l)}

/* --- animaciones --- */
@keyframes sube{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@keyframes pop{from{opacity:0;transform:scale(.86)}to{opacity:1;transform:scale(1)}}
@keyframes flota{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-9px) rotate(-1.2deg)}}
@keyframes marea{0%{transform:translateY(100%)}38%,58%{transform:translateY(0)}100%{transform:translateY(-100%)}}
.entra{animation:pop .6s .2s cubic-bezier(.34,1.5,.6,1) backwards}

/* ============ RESPONSIVE (W-08) ======================================== */
@media (max-width:960px){
 .home{grid-template-columns:1fr}
 .hilos-row{grid-template-columns:1fr}
 .duo{grid-template-columns:1fr}
 .foot-in{grid-template-columns:1fr;gap:30px}
 .navlinks{display:none}
}
@media (max-width:760px){
 .tv{font-size:15.5px}
 .bottom{display:flex;position:fixed;bottom:0;left:0;right:0;z-index:90;background:var(--paper);
  border-top:var(--bd);padding-bottom:env(safe-area-inset-bottom)}
 .view{padding-bottom:112px}
 .foot-legal{padding-bottom:100px}
 /* el mapa nunca desaparece: la hoja sube en tres alturas por encima */
 .home{position:relative;grid-template-columns:1fr!important;
  height:calc(100vh - var(--navh,62px));height:calc(100dvh - var(--navh,62px))}
 .mapa-wrap{height:100%;border-right:0}
 .baja{display:none}
 .banner{min-height:240px}
 .banner.alto{min-height:280px}
 .panel-tab{display:none}
 .panel{position:absolute;left:0;right:0;bottom:58px;z-index:70;max-height:74vh;
  border-top:var(--bd);border-radius:24px 24px 0 0;
  box-shadow:0 -8px 0 rgba(27,58,36,.12);
  transition:transform .45s cubic-bezier(.3,1.2,.5,1)}
 .panel[data-h=asomado]{transform:translateY(calc(100% - 132px))}
 .panel[data-h=medio]{transform:translateY(40%)}
 .panel[data-h=completo]{transform:translateY(0)}
 .panel[data-h=oculto]{transform:translateY(calc(100% - 46px))}
 .home[data-panel=cerrado] .panel{opacity:1;visibility:visible;overflow-y:auto}
 .tirador{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;
  width:100%;min-height:46px;padding:11px;border-bottom:2.5px solid var(--ink);
  font-family:var(--mono);font-size:10px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;
  color:var(--ink2)}
 .tirador::before{content:"";width:44px;height:5px;border-radius:3px;background:var(--ink);opacity:.35}
 .banner.banner,.banner.alto{min-height:290px}
 .banner-txt{margin-top:130px}
 .lista-item{grid-template-columns:72px 1fr;gap:16px}
 .li-foto{width:72px;height:72px}
 .lista-item .flecha{display:none}
 .inset{display:none}
 .grid-gal{grid-template-columns:repeat(auto-fill,minmax(130px,1fr))}
 /* los hilos y el contexto pasan a carrusel horizontal */
 .hilos-row,.ctx-grid{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;gap:14px;
  padding-bottom:12px;-webkit-overflow-scrolling:touch}
 .hilos-row>*,.ctx-grid>*{flex:0 0 80%;scroll-snap-align:start}
 .foot-legal{flex-direction:column}
 .dos-col{column-count:1}
}
@media (prefers-reduced-motion:reduce){
 .tv *,.tv *::before,.tv *::after{animation:none!important;transition:none!important}
}
.dos-col{margin-top:22px;column-count:2;column-gap:38px;color:var(--ink2);font-size:15.5px}
`;


/* ===================== APP =============================================== */
/* Qué se oye al entrar a cada sección, durante la marea */
const AVISO_VISTA = {
  home: "ola", historias: "marimba", nucleo: "marimba",
  saberes: "hojas", saber: "hojas", visita: "gaviota",
  archivo: "pajaros", comparte: "campana", proyecto: "madera",
};

/* Acerca o aleja manteniendo fijo el centro de lo que se está viendo */
function acercar(v, factor) {
  const nz = Math.min(3, Math.max(1, v.z * factor));
  const lx = (720 - v.tx) / v.z, ly = (450 - v.ty) / v.z;
  return limitaVista(nz, 720 - nz * lx, 450 - nz * ly);
}

const ACC_SABER = { viche: "cacao", gastronomia: "coral", danza: "coral", musica: "sky", manglar: "" };
const INICIO = {
  t: "El proyecto", n: "Un territorio que se cuenta a sí mismo",
  pl: "Nuquí · Chocó · Pacífico colombiano",
  tx: "Recorre la costa: cada retrato es una persona y cada persona es una puerta. Empieza por donde quieras.",
  go: null, dest: null,
};

export default function TerritoriosVivos() {
  const [route, setRoute] = useState({ v: "home" });
  const [marea, setMarea] = useState(null);
  const lock = useRef(false);
  const [sonido, setSonido] = useState(true);   // arranca encendido
  const [volumen, setVolumen] = useState(22);
  const [verVol, setVerVol] = useState(false);
  const volT = useRef(null);

  /* La barra asoma al encender el sonido y se repliega sola.
     Vuelve a asomar con el cursor encima o al llegar con el teclado. */
  const abrirVol = useCallback(() => { clearTimeout(volT.current); setVerVol(true); }, []);
  const cerrarVol = useCallback((ms = 1200) => {
    clearTimeout(volT.current);
    volT.current = setTimeout(() => setVerVol(false), ms);
  }, []);
  useEffect(() => {
    if (sonido) { abrirVol(); cerrarVol(3200); }
    else { clearTimeout(volT.current); setVerVol(false); }
  }, [sonido, abrirVol, cerrarVol]);
  useEffect(() => () => clearTimeout(volT.current), []);
  const [visitados, setVisitados] = useState([]);      // en producción: localStorage
  const [gran, setGran] = useState(false);
  const [vista, setVista] = useState({ z: 1, tx: 0, ty: 0 });
  const [info, setInfo] = useState(INICIO);
  const [sheet, setSheet] = useState("asomado");
  const [mas, setMas] = useState(false);
  const [flotantes, setFlotantes] = useState(false);
  const [ficha, setFicha] = useState(null);
  const [foco, setFoco] = useState(null);
  const [bienvenida, setBienvenida] = useState(false);
  const [panel, setPanel] = useState("abierto");   // la ficha se puede guardar
  const movil = useMedia("(max-width:760px)");
  const navRef = useRef(null);
  const sonar = usePaisajeSonoro(sonido, volumen);

  /* El alto real de la barra superior alimenta --navh: así el mapa ocupa
     exactamente la primera pantalla sin números mágicos ni recortes. */
  useLayoutEffect(() => {
    const medir = () => {
      const h = navRef.current ? navRef.current.offsetHeight : 0;
      if (h) document.documentElement.style.setProperty("--navh", h + "px");
    };
    medir();
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(medir) : null;
    if (ro && navRef.current) ro.observe(navRef.current);
    window.addEventListener("resize", medir);
    return () => { window.removeEventListener("resize", medir); if (ro) ro.disconnect(); };
  }, []);

  const nucleo = route.v === "nucleo"
    ? (route.slug === EXPANSION.slug ? EXPANSION : NUCLEOS.find(n => n.slug === route.slug)) : null;
  const saber = route.v === "saber" ? SABERES.find(s => s.slug === route.slug) : null;
  const acc = saber ? (ACC_SABER[saber.slug] || "")
    : route.v === "visita" ? "sky"
      : (route.v === "archivo" || route.v === "comparte") ? "coral" : "";

  const go = useCallback((v, slug) => {
    if (lock.current) return;
    if (v === route.v && slug === route.slug) { setMas(false); return; }
    const t = v === "nucleo"
      ? (slug === EXPANSION.slug ? EXPANSION.corto1 : (NUCLEOS.find(n => n.slug === slug)?.corto1 || "Historias"))
      : v === "saber" ? (SABERES.find(s => s.slug === slug)?.nombre || "Saberes")
        : ({
          home: "El mapa de Nuquí", historias: "Las historias", saberes: "Los saberes",
          visita: "Visita Nuquí", archivo: "Archivo Vivo",
          comparte: "Comparte tu historia", proyecto: "El Proyecto",
        }[v] || "Territorios Vivos");
    lock.current = true;
    sonar(AVISO_VISTA[v] || "ola");
    setMarea(t); setMas(false); setFicha(null);
    setTimeout(() => { setRoute({ v, slug }); window.scrollTo({ top: 0 }); }, 480);
    setTimeout(() => { setMarea(null); lock.current = false; }, 1040);
    if (v === "nucleo" && slug) setVisitados(a => a.includes(slug) ? a : [...a, slug]);
  }, [route.v, route.slug, sonar]);

  const abrirFoco = useCallback((e, cap) => setFoco({ cap }), []);
  useEffect(() => {
    const h = e => { if (e.key === "Escape") { setFoco(null); setFicha(null); setMas(false); setBienvenida(false); } };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, []);

  const ciclar = () => setSheet(s => s === "asomado" ? "medio" : s === "medio" ? "completo" : "asomado");
  const hover = c => { setInfo(c); if (movil && sheet === "asomado") setSheet("medio"); };

  return (
    <div className="tv" data-acc={acc} data-home={route.v === "home"}>
      <style>{CSS}</style>

      {/* transición de marea: el agua sube, tapa, y se retira */}
      {marea && (
        <div className="marea" aria-hidden="true">
          <div className="marea-agua" />
          <Ola />
          <div className="marea-ola"><Ola /></div>
          <div className="marea-txt"><b>{marea}</b><i>Territorios Vivos</i></div>
        </div>
      )}

      <nav className="nav" ref={navRef}>
        <button className="marca" onClick={() => go("home")}>
          <span className="marca-n">Territorios Vivos</span>
          <span className="marca-s">Relatos del Pacífico</span>
        </button>
        <div className="navlinks">
          {NAV.map(([v, l]) => (
            <button key={v} className="navlink" onClick={() => go(v)}
              aria-current={route.v === v || (v === "historias" && route.v === "nucleo")
                || (v === "saberes" && route.v === "saber")
                || (v === "archivo" && route.v === "comparte") ? "page" : undefined}>{l}</button>
          ))}
        </div>
        <div className="audio" onMouseEnter={() => sonido && abrirVol()}
          onMouseLeave={() => sonido && cerrarVol()}>
        <button className="sonido" data-on={sonido} aria-pressed={sonido}
          onClick={() => setSonido(s => !s)} title="Paisaje sonoro del Pacífico · provisional, sintetizado hasta que llegue AUD-G.1">
          <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor"
            strokeWidth="2.2" strokeLinecap="round">
            <path d="M4 9v6h3l5 4V5L7 9z" />
            {sonido ? <path d="M16 8.5a5 5 0 0 1 0 7M18.5 6a8.5 8.5 0 0 1 0 12" />
              : <path d="M16.5 9.5l5 5m0-5l-5 5" />}
          </svg>
          {sonido ? "on" : "off"}
        </button>
        {sonido && (
          <label className="vol" data-ver={verVol} title="Volumen del paisaje sonoro">
            <span>Vol</span>
            <input type="range" min="0" max="60" value={volumen}
              onChange={e => { abrirVol(); setVolumen(Number(e.target.value)); }}
              onFocus={abrirVol} onBlur={() => cerrarVol()}
              aria-label="Volumen del paisaje sonoro" />
          </label>
        )}
        </div>
      </nav>

      {/* ============================ W-01 · HOME ========================== */}
      {route.v === "home" && (
        <div className="home" data-panel={panel}>
          <h1 className="sr-only">Territorios Vivos · Nuquí, Chocó: el territorio contado por su gente</h1>
          <div className="mapa-wrap">
            <MapaVivo gran={gran} vista={vista} setVista={setVista} flotantes={flotantes}
              activo={info.slug} onHover={hover} onFicha={setFicha}
              onNucleo={s => go("nucleo", s)} onSaber={s => go("saber", s)} />

            {panel === "cerrado" && (
              <button className="panel-tab" onClick={() => setPanel("abierto")}>
                Abrir la ficha ◂
              </button>
            )}

            <div className="mapa-ctrl">
              <button className="ctrl-b" data-on={gran} onClick={() => setGran(g => !g)}>
                {gran ? "Volver a Nuquí" : "Ver el Chocó ⤢"}
              </button>
              <div className="zoom" role="group" aria-label="Zoom del mapa">
                <button onClick={() => setVista(v => acercar(v, 1.35))} aria-label="Acercar">+</button>
                <button onClick={() => setVista(v => acercar(v, 1 / 1.35))} aria-label="Alejar">−</button>
              </div>
              <button className="ctrl-b coral" data-on={flotantes}
                onClick={() => setFlotantes(f => !f)}>Fase 2 · comunidad</button>
            </div>

            <div className="inset">
              <svg viewBox="0 0 206 240" aria-hidden="true">
                <path d={COLOMBIA} fill="#EDE7C4" stroke="#1B3A24" strokeWidth="1.6" />
                <path d={CHOCO} fill="#5CB747" stroke="#1B3A24" strokeWidth="1.6" />
                <circle cx={NI[0]} cy={NI[1]} r="4.5" fill="#E8603A" stroke="#1B3A24" strokeWidth="1.6" />
              </svg>
              <span className="inset-l">Estás aquí · Nuquí, Chocó</span>
            </div>

            <button className="baja" onClick={() => document.getElementById("abajo")
              ?.scrollIntoView({ behavior: "smooth", block: "start" })}>
              Sigue bajando ↓
            </button>

            <span className="mapa-pie">
              {movil ? "Pellizca para acercar · arrastra para moverte"
                : vista.z > 1 ? "Arrastra para moverte por el mapa · rueda para acercar"
                  : "Pasa el cursor por un punto · rueda o + para acercar"}
            </span>
          </div>

          <aside className="panel" data-h={sheet}>
            <button className="tirador" onClick={ciclar}>
              {sheet === "completo" ? "Bajar" : "Desliza hacia arriba"}
            </button>

            <div className="panel-cab">
              <span>Ficha del territorio</span>
              <button className="guardar" onClick={() => setPanel("cerrado")}
                title="Guardar la ficha para ver el mapa completo">Guardar ▸</button>
            </div>

            <div className="panel-b">
              <span className="eyebrow">{info.t}</span>
              <div className="info-n">{info.n}</div>
              <span className="inset-l">{info.pl}</span>
              <p className="info-p">{info.tx}</p>
              {info.dest && (
                <button className="cta" style={{ marginTop: 16 }} onClick={() => go(...info.dest)}>
                  {info.go}<span className="flecha">→</span>
                </button>
              )}
            </div>

            <div className="panel-b">
              <span className="eyebrow">Chachita te recibe · 0:35</span>
              <div style={{ marginTop: 12 }}>
                <Media code="VID-01.1" fmt="video" ratio="16/9" dur="0:35"
                  cap="Voz de bienvenida · se ofrece en la primera visita"
                  est="Por producir" fase="pendiente" onPlay={() => setBienvenida(true)} />
              </div>
            </div>

            <div className="panel-b">
              <span className="eyebrow">Tu exploración</span>
              <div className="brujula" aria-hidden="true">
                {[...NUCLEOS.map(n => n.slug), EXPANSION.slug].map(s =>
                  <i key={s} data-on={visitados.includes(s)} />)}
              </div>
              <span className="inset-l">{visitados.length} de 5 territorios · se guarda en este equipo</span>
            </div>

            <div className="panel-b">
              <button className="cta" onClick={() => go("historias")}>
                Empieza por una historia<span className="flecha">→</span>
              </button>
              <button className="cta cta-2" style={{ marginTop: 12 }} onClick={() => go("saberes")}>
                O explora por saberes<span className="flecha">→</span>
              </button>
            </div>

            <div className="panel-b">
              <SelloSEO url="territoriosvivos.co/"
                titulo="Territorios Vivos: Relatos del Pacífico | Nuquí, Chocó"
                meta="Explora Nuquí a través de las voces de su gente: historias, saberes ancestrales y turismo que cuida el territorio. Un universo documental del Pacífico colombiano."
                datos="WebSite + Organization" />
            </div>
          </aside>
        </div>
      )}

      {route.v === "historias" && <VHistorias go={go} visitados={visitados} />}
      {route.v === "nucleo" && nucleo && <VNucleo n={nucleo} go={go} onFoco={abrirFoco} />}
      {route.v === "saberes" && <VSaberes go={go} />}
      {route.v === "saber" && saber && <VSaber s={saber} go={go} onFoco={abrirFoco} />}
      {route.v === "visita" && <VVisita go={go} onFoco={abrirFoco} />}
      {route.v === "archivo" && <VArchivo go={go} onFicha={setFicha} />}
      {route.v === "comparte" && <VComparte go={go} />}
      {route.v === "proyecto" && <VProyecto go={go} />}

      {route.v === "home" && (
        <section className="home-abajo wash" id="abajo">
          <span className="eyebrow">Cómo se recorre</span>
          <h2 className="h2" style={{ marginTop: 10 }}>Tres formas de entrar al territorio</h2>
          <p className="sub">El mapa no es un menú de videos: es el territorio. Estas son las
            puertas que abre.</p>
          <div className="cards">
            {[
              { il: "palma", k: "Historias", t: "Las personas son las puertas",
                d: "Cinco núcleos: cuatro en Nuquí y una expansión en Quibdó. Cada uno abre con su retrato y su corto.",
                v: "historias" },
              { il: "tortuga", k: "Saberes", t: "Los saberes atraviesan a varias personas",
                d: "Viche, cocina, danza, música y manglar. Ninguno es anónimo y ninguno es destino final.",
                v: "saberes" },
              { il: "cangrejo", k: "Archivo Vivo", t: "La comunidad también escribe",
                d: "Las voces de Nuquí se suman al archivo con crédito visible y su lugar en el mapa.",
                v: "archivo" },
            ].map(p => (
              <Zona key={p.k} className="card principio" label={p.t} onClick={() => go(p.v)}>
                <span className="principio-il" aria-hidden="true">
                  <svg viewBox="-70 -70 140 140" width="42" height="42">
                    {p.il === "palma" ? <IlPalma s={1.1} />
                      : p.il === "tortuga" ? <g transform="scale(.6)"><IlTortuga /></g>
                        : <g transform="scale(.75)"><IlCangrejo /></g>}
                  </svg>
                </span>
                <span className="eyebrow">{p.k}</span>
                <h3 className="h3">{p.t}</h3>
                <p className="sub">{p.d}</p>
                <span className="hilo-to">Entrar <span className="flecha">→</span></span>
              </Zona>
            ))}
          </div>
          <Separador il="cacao" />
        </section>
      )}

      <Footer onGo={go} />

      <nav className="bottom" aria-label="Navegación principal">
        {NAV_MOVIL.map(([v, l, d]) => (
          <button key={v} className="bottom-btn" onClick={() => v === "mas" ? setMas(true) : go(v)}
            aria-current={route.v === v || (v === "historias" && route.v === "nucleo")
              || (v === "saberes" && route.v === "saber") ? "page" : undefined}>
            <IconoNav d={d} />{l}
          </button>
        ))}
      </nav>

      {mas && (<>
        <div className="scrim" onClick={() => setMas(false)} />
        <div className="modal" role="dialog" aria-label="Más secciones">
          <button className="modal-x" onClick={() => setMas(false)} aria-label="Cerrar">✕</button>
          <span className="eyebrow">Más</span>
          <h2 className="h2" style={{ margin: "10px 0 20px" }}>El resto del universo</h2>
          {[["archivo", "Archivo Vivo", "La voz de la comunidad"],
            ["proyecto", "El Proyecto", "Equipo, aliados, blog y contacto"]].map(([v, l, d]) => (
              <button key={v} className="cta" style={{ marginBottom: 12, maxWidth: "none" }}
                onClick={() => go(v)}>
                <span style={{ textAlign: "left", lineHeight: 1.3 }}>{l}<br />
                  <span style={{ fontSize: 10, opacity: .75 }}>{d}</span></span>
                <span className="flecha">→</span>
              </button>
            ))}
        </div>
      </>)}

      {foco && (<>
        <div className="scrim" onClick={() => setFoco(null)} />
        <div className="modal" role="dialog" aria-label={foco.cap} style={{ width: "min(94vw,1000px)" }}>
          <button className="modal-x" onClick={() => setFoco(null)} aria-label="Cerrar">✕</button>
          <span className="eyebrow">{foco.cap}</span>
          <div style={{ marginTop: 14 }}>
            <Media code="—" fmt="video" ratio="16/9" cap="Aquí se incrusta el reproductor"
              est="Por integrar" fase="proceso" />
          </div>
          <p className="hint" style={{ marginTop: 14 }}>
            En producción: calidad adaptativa (HLS o Vimeo), póster liviano, sin autoplay y con
            subtítulos activables. Cierra con ✕, Esc o clic afuera.
          </p>
        </div>
      </>)}

      {bienvenida && (<>
        <div className="scrim" onClick={() => setBienvenida(false)} />
        <div className="modal" role="dialog" aria-label="Bienvenida de Chachita">
          <button className="modal-x" onClick={() => setBienvenida(false)} aria-label="Cerrar">✕</button>
          <span className="eyebrow">Chachita te recibe · 0:35</span>
          <div style={{ marginTop: 14 }}>
            <Media code="VID-01.1" fmt="video" ratio="16/9" dur="0:35"
              cap="Video de bienvenida con subtítulos" est="Por producir" fase="pendiente" />
          </div>
          <div className="tools"><span className="tool">CC · subtítulos</span>
            <span className="tool">Transcripción</span></div>
          <button className="cta" style={{ marginTop: 18 }}
            onClick={() => { setBienvenida(false); go("nucleo", "chachita"); }}>
            Conocer a Chachita<span className="flecha">→</span>
          </button>
        </div>
      </>)}

      {ficha !== null && (<>
        <div className="scrim" onClick={() => setFicha(null)} />
        <div className="ficha" role="dialog" aria-label={`Historia de la comunidad: ${UGC[ficha].t}`}>
          <div style={{ position: "relative" }}>
            <button className="modal-x" onClick={() => setFicha(null)} aria-label="Cerrar">✕</button>
            <Media code="UGC" ratio="4/5" dur={UGC[ficha].dur}
              fmt={UGC[ficha].tipo === "video" ? "video" : UGC[ficha].tipo === "audio" ? "audio" : "imagen"} />
          </div>
          <div style={{ padding: "18px 20px" }}>
            <span className="chip fase2">Fase 2</span>
            <h3 className="h3" style={{ marginTop: 12 }}>{UGC[ficha].t}</h3>
            <div className="ugc-meta">
              <span>{UGC[ficha].a}</span><span className="pin">◈ {UGC[ficha].p}</span>
            </div>
            <button className="cta cta-2" style={{ marginTop: 16 }} onClick={() => go("archivo")}>
              Ver historia completa<span className="flecha">→</span>
            </button>
          </div>
          <div className="ficha-nav">
            <button onClick={() => setFicha(f => (f - 1 + UGC.length) % UGC.length)}>← Anterior</button>
            <button onClick={() => setFicha(f => (f + 1) % UGC.length)}>Siguiente →</button>
          </div>
        </div>
      </>)}
    </div>
  );
}

