function VArchivo({ go, onFicha }) {
  const [f, setF] = useState("Todos");
  const lista = ["Video", "Foto", "Audio", "Texto"].includes(f)
    ? UGC.filter(u => u.tipo === f.toLowerCase()) : UGC;
  return (
    <div className="view wrap">
      <Migas trail={[{ l: "Mapa", to: ["home"] }, { l: "Archivo Vivo" }]} onGo={go} />
      <Banner code="IMG-06.0" kicker="El archivo vivo"
        titulo={<>Aquí el territorio se <Em>cuenta a sí mismo</Em></>}
        lede="Las voces de Nuquí siguen creciendo. Comparte tu historia y encuentra tu lugar en el mapa."
        cap="Banner de sección" est="Por seleccionar" fase="proceso" />

      <div className="convoca">
        <div>
          <span className="eyebrow" style={{ color: "var(--ink)" }}>Convocatoria del trimestre</span>
          <h2 className="h2" style={{ marginTop: 10 }}>«Mi lugar del manglar»</h2>
          <p className="sub" style={{ color: "var(--ink)" }}>Cierra el 30 de septiembre.
            La revisa el comité antes de publicarse.</p>
        </div>
        <button className="cta" onClick={() => go("comparte")}>
          Comparte tu historia<span className="flecha">→</span>
        </button>
      </div>

      <div className="filtros" role="group" aria-label="Filtros del archivo">
        {FILTROS.map(x => (
          <button key={x} className="filtro" aria-pressed={f === x} onClick={() => setF(x)}>{x}</button>
        ))}
      </div>

      <div className="ugc-grid">
        {lista.map(u => (
          <Zona key={u.t} className="ugc" label={u.t} onClick={() => onFicha(UGC.indexOf(u))}>
            <span className="ugc-media">
              {u.tipo === "audio"
                ? <span className="onda" aria-hidden="true">{Array.from({ length: 16 }, (_, k) =>
                  <i key={k} style={{ height: `${10 + Math.abs(Math.sin(k * 1.7)) * 30}px` }} />)}</span>
                : <CampoVacio fmt={u.tipo === "video" ? "video" : "imagen"} code="UGC" />}
              {u.dur && <span className="dur">{u.dur}</span>}
            </span>
            <span className="ugc-pie">
              <span className="ugc-t">{u.t}</span>
              <span className="ugc-meta">
                <span>{u.a}</span><span className="pin">◈ {u.p}</span>
                <span className="chip" style={{ fontSize: 9, padding: "3px 8px" }}>{u.tipo}</span>
              </span>
            </span>
          </Zona>
        ))}
      </div>
      <p className="hint" style={{ marginTop: 20 }}>Todas las tarjetas comparten tamaño y pie:
        título, crédito del autor, pin de lugar y etiqueta de formato. El formato se adapta dentro
        del contenedor; se estandariza el contenedor, no la persona.</p>

      <SelloSEO url="territoriosvivos.co/archivo-vivo"
        titulo="Archivo Vivo: el territorio se cuenta a sí mismo"
        meta="Historias enviadas por la comunidad de Nuquí. Comparte la tuya y encuentra tu lugar en el mapa del Pacífico. Un archivo colectivo en permanente crecimiento."
        datos="CollectionPage" />
    </div>
  );
}

/* ===================== W-06b · COMPARTE ================================== */
function VComparte({ go }) {
  const [tipo, setTipo] = useState("Video");
  const [ok, setOk] = useState(false);
  const [cons, setCons] = useState(false);
  const [nombre, setNombre] = useState("");
  const [error, setError] = useState(null);
  function enviar() {
    if (!nombre.trim()) return setError("Escribe tu nombre para que podamos darte el crédito.");
    if (!cons) return setError("Necesitamos tu autorización para poder publicar la historia.");
    setError(null); setOk(true);
  }
  return (
    <div className="view wrap">
      <Migas trail={[{ l: "Mapa", to: ["home"] }, { l: "Archivo Vivo", to: ["archivo"] },
        { l: "Comparte tu historia" }]} onGo={go} />
      <Head kicker="Comparte tu historia" h={<>Tu historia en el <Em>mapa</Em></>}
        p="La revisa el comité de Territorios Vivos (Doinmedia y representantes comunitarios) antes de publicarse. Te avisamos en cualquier caso." />

      {ok ? (
        <div className="ok" style={{ maxWidth: 580 }}>
          <h3 className="h3">Tu historia está en revisión del comité</h3>
          <p className="sub">Te escribimos al correo cuando haya decisión. Si se publica, aparecerá
            en el Archivo Vivo con tu nombre y el pin de tu lugar.</p>
          <div style={{ marginTop: 18, display: "flex", gap: 12, flexWrap: "wrap" }}>
            <button className="cta cta-2" style={{ maxWidth: 250 }} onClick={() => go("archivo")}>
              Ver el archivo<span className="flecha">→</span></button>
            <button className="cta cta-2" style={{ maxWidth: 250 }} onClick={() => setOk(false)}>
              Enviar otra<span className="flecha">→</span></button>
          </div>
        </div>
      ) : (
        <div className="form">
          <div className="field">
            <label className="label" htmlFor="c-n">Tu nombre</label>
            <input className="input" id="c-n" value={nombre} onChange={e => setNombre(e.target.value)}
              placeholder="Nombre y apellido" />
            <span className="hint">Aparece como crédito en la tarjeta. No publicamos historias anónimas.</span>
          </div>
          <div className="field">
            <label className="label" htmlFor="c-l">¿Dónde ocurre?</label>
            <select className="select" id="c-l" defaultValue="">
              <option value="" disabled>Elige el lugar en el mapa</option>
              {["Nuquí", "Panguí", "Coquí", "Termales", "Arusí", "Jurubidá", "Tribugá", "Otro"]
                .map(l => <option key={l}>{l}</option>)}
            </select>
            <span className="hint">El pin de lugar es obligatorio: sitúa tu historia en el territorio.</span>
          </div>
          <div className="field">
            <span className="label">Tipo de historia</span>
            <div className="radios">
              {["Video", "Foto", "Audio", "Texto"].map(t => (
                <button key={t} className="radio" aria-pressed={tipo === t} onClick={() => setTipo(t)}>{t}</button>
              ))}
            </div>
          </div>
          <div className="field">
            <span className="label">Sube tu archivo</span>
            <div className="drop">Arrastra aquí o toca para elegir<br />
              <b style={{ color: "var(--coral-d)" }}>máximo {tipo === "Video" ? "100 MB de video"
                : tipo === "Foto" ? "15 MB de imagen" : "25 MB de audio"}</b></div>
            <span className="hint">Los límites se muestran antes de subir para evitar errores.</span>
          </div>
          <div className="field">
            <label className="label" htmlFor="c-t">Cuéntanos en pocas líneas</label>
            <textarea className="textarea" id="c-t" placeholder="Opcional" />
          </div>
          <button className="check" aria-pressed={cons} onClick={() => setCons(c => !c)}>
            <span className="box">{cons ? "✓" : ""}</span>
            <span>Autorizo el uso de esta historia en Territorios Vivos y confirmo que tengo el
              consentimiento de las personas que aparecen. Si hay menores de edad, cuento con la
              autorización de su acudiente.</span>
          </button>
          {error && <p className="hint" style={{ color: "var(--coral-d)", fontWeight: 700 }}>{error}</p>}
          <button className="cta" onClick={enviar}>Enviar para revisión<span className="flecha">→</span></button>
          <p className="hint">El consentimiento es una aceptación digital dentro de este
            formulario, no un archivo. Para las comunidades protagonistas se firma aparte un acta
            CPLI presencial.</p>
        </div>
      )}
    </div>
  );
}

/* ===================== W-07 · EL PROYECTO =============================== */
